INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(1, 'НЕКОТОРЫЕ ИНФЕКЦИОННЫЕ И ПАРАЗИТАРНЫЕ БОЛЕЗНИ', 'A00-B99', NULL, NULL, 21, 'Включены: болезни, обычно рассматриваемые как передающиеся, или трансмиссивные\nИсключены: носительство или подозреваемое носительство возбудителя инфекционной болезни (Z22.-) некоторые локализованные инфекции - см. классы, относящиеся к системам органов инфекционные и паразитарные болезни, осложняющие беременность, роды и послеродовой период (за исключением акушерского столбняка и болезни, вызванной вирусом иммунодефицита человека [ВИЧ] (O98.-) инфекционные и паразитарные болезни, характерные для перинатального периода (за исключением перинатального столбняка, врожденного сифилиса, перинатальной гонококковой инфекции и перинатального заболевания, вызванного вирусом иммунодефицита человека [ВИЧ] (P35-P39) грипп и другие острые респираторные инфекции (J00- J22)\nВ этот класс входят следующие блоки:\nA00-A09 Кишечные инфекции\nA15-A19 Туберкулез\nA20-A28 Некоторые бактериальные зоонозы\nA30-A49 Другие бактериальные болезни\nA50-A64 Инфекции, передающиеся преимущественно половым путем\nA65-A69 Другие болезни, вызываемые спирохетами\nA70-A74 Другие болезни, вызываемые хламидиями\nA75-A79 Риккетсиозы\nA80-A89 Вирусные инфекции центральной нервной системы\nA90-A99 Вирусные лихорадки, передаваемые членистоногими, и вирусные геморрагические лихорадки\nB00-B09 Вирусные инфекции, характеризующиеся поражениями кожи и слизистых оболочек\nB15-B19 Вирусный гепатит\nB20-B24 Болезнь, вызванная вирусом иммунодефицита человека [ВИЧ]\nB25-B34 Другие вирусные болезни\nB35-B49 Микозы\nB50-B64 Протозойные болезни\nB65-B83 Гельминтозы\nB85-B89 Педикулез, акариаз и другие инфестации\nB90-B94 Последствия инфестационных и паразитарных болезней\nB95-B97 Бактериальные, вирусные и другие инфекционные агенты\nB99 Другие инфекционные болезни');
