INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(70, 'Другой гастроэнтерит и колит инфекционного и неуточненного происхождения', 'A09', 2, 'A00-A09', 2, 'Примечание. В странах, где диагнозы, перечисленные в рубрике A09, при отсутствии уточнения могут рассматриваться как болезни неинфекционного происхождения, указанные состояния должны классифицироваться в рубрике K52.9 Катар кишечный [интестинальный] Колит } БДУ Энтерит } геморрагический Гастроэнтерит } септический Диарея: * БДУ * дизентерийная * эпидемическая Инфекционная диарея БДУ Исключены: вызванные бактериями, простейшими, вирусами и другими уточненными инфекционными агентами (A00-A08) неинфекционная диарея (K52.9) . неонатальная (P78.3)');
