INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(71, 'ТУБЕРКУЛЕЗ', 'A15-A19', 1, 'A00-B99', 5, 'Включены: инфекции, вызванные Mycobacterium tuberculosis и Mycobacterium bovis\nИсключены: врожденный туберкулез (P37.0) пневмокониоз, связанный с туберкулезом (J65) последствия туберкулеза (B90.-) силикотуберкулез (J65)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(72, 'Туберкулез органов дыхания, подтвержденный бактериологически и гистологически', 'A15', 71, 'A15-A19', 10, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(73, 'Туберкулез легких, подтвержденный бактериоскопически с наличием или отсутствием роста культуры', 'A15.0', 72, 'A15', 0, 'Туберкулезная(ый): . бронхоэктазия } подтверждение бактериоскопически . фиброз легкого } с наличием или отсутствием роста . пневмония } культуры . пневмоторакс }');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(74, 'Туберкулез легких, подтвержденный только ростом культуры', 'A15.1', 72, 'A15', 0, 'Состояния, перечисленные в рубрике A15.0, подтвержденные только ростом культуры');
