INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(257, 'Бактериальная инфекция неуточненной локализации', 'A49', 170, 'A30-A49', 6, 'Исключены: бактериальные агенты как причина болезней, классифицированных в других классах (B95-B96) инфекция, вызванная хламидиями, БДУ (A74.9) . менингококковая инфекция БДУ (A39.9) . инфекция, вызванная риккетсиями, БДУ (A79.9) . инфекция, вызванная спирохетами, БДУ (A69.9)');
