INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(264, 'ИНФЕКЦИИ, ПЕРЕДАЮЩИЕСЯ ПРЕИМУЩЕСТВЕННО ПОЛОВЫМ ПУТЕМ', 'A50-A64', 1, 'A00-B99', 13, 'Исключено: болезнь, вызванная вирусом иммунодефицита человека [ВИЧ] (B20-B24) неспецифические и негонококковые уретриты (N34.1) болезнь Рейтера (M02.3)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(265, 'Врожденный сифилис', 'A50', 264, 'A50-A64', 9, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(266, 'Ранний врожденный сифилис с симптомами', 'A50.0', 265, 'A50', 0, 'Любое врожденное сифилитическое состояние, уточненное как раннее или проявившееся в возрасте до двух лет. Ранний врожденный сифилис: . кожи . кожи и слизистых оболочек . висцеральный Ранний врожденный сифилитический(ая): . ларингит . окулопатия . остеохондропатия . фарингит . пневмония . ринит');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(267, 'Ранний врожденный сифилис скрытый', 'A50.1', 265, 'A50', 0, 'Врожденный сифилис без клинических проявлений с положительной серологической реакцией и отрицательным тестом спинномозговой жидкости в возрасте до двух лет.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(268, 'Ранний врожденный сифилис неуточненный', 'A50.2', 265, 'A50', 0, 'Врожденный сифилис БДУ, проявившийся в возрасте до двух лет.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(269, 'Позднее врожденное сифилитическое поражение глаз', 'A50.3', 265, 'A50', 0, 'Поздний врожденный сифилитический интерстициальный кератит+ (H19.2*) Поздняя врожденная сифилитическая окулопатия НКДР (H58.8*) Исключена: триада Гетчинсона (A50.5)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(270, 'Поздний врожденный нейросифилис [ювенильный нейросифилис]', 'A50.4', 265, 'A50', 0, 'Деменция паралитическая ювенильная Ювенильный(ая): . прогрессивный паралич . спинная сухотка . табопаралич Поздний врожденный сифилитический(ая): . энцефалит+ (G05.0*) . менингит+ (G01*) . пилоневропатия+ (G63.0*) При необходимости идентифицировать любое связанное с данным заболеванием психическое расстройство используют дополнительный код. Исключена: триада Гетчинсона (A50.5)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(271, 'Другие формы позднего врожденного сифилиса с симптомами', 'A50.5', 265, 'A50', 0, 'Любое врожденное сифилитическое состояние, уточненное как позднее или проявившееся через два года или более с момента рождения. Суставы Клаттона (M03.1*) Гетчинсона: . зубы . триада Поздний врожденный: . кардиоваскулярный сифилис+ (I98.*) . сифилитическая: . артропатия+ (M03.1*) . остеохондропатия+ (M90.2*) Сифилитический седловидный нос');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(272, 'Поздний врожденный сифилис скрытый', 'A50.6', 265, 'A50', 0, 'Врожденный сифилис без клинических проявлений, с положительной серологической реакцией и отрицательным тестом спинномозговой жидкости в возрасте двух и более лет.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(273, 'Поздний врожденный сифилис неуточненный', 'A50.7', 265, 'A50', 0, 'Врожденный сифилис БДУ в возрасте двух и более лет');
