INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(285, 'Нейросифилис с симптомами', 'A52.1', 283, 'A52', 0, 'Артропатия Шарко (M14.6*) Поздний сифилитический(ая): . неврит слухового нерва+ (H49.0*) . энцефалит+ (G05.0*) . менингит+ (G01*) . атрофия зрительного нерва+ (H48.0*) . полиневропатия+ (G63.0*) . ретробульбарный неврит+ (H48.1*) Сифилитический паркинсонизм+ (G22*) Спинная сухотка');
