INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(288, 'Другие симптомы позднего сифилиса', 'A52.7', 283, 'A52', 0, 'Сифилитическое поражение почечных клубочков+ (N08.0*) Гумма (сифилитическая) } любых локализаций, Сифилис поздний, или } кроме классифицированных третичный } в рубриках A52.0-A52.3 Поздний сифилитический(ая): . бурсит+ (M73.1*) . хориоретинит+ (H32.0) . эписклерит+ (H19.0*) . воспалительное заболевание женских тазовых органов (N74.2*) . лейкодерма+ (L99.8*) . окулопатия НКДР+ (H58.8*) . перитонит+ (K67.2*) Сифилис (без уточнения стадии): . кости+ (M90.2*) . печени+ (K77.0*) . легкого+ (J99.8*) . мышц (M63.0*) . синовиальный+ (M68.0*)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(289, 'Поздний сифилис скрытый', 'A52.8', 283, 'A52', 0, 'Сифилис (приобретенный) без клинических проявлений, с положительной серологической реакцией и отрицательной пробой спинномозговой жидкости, давностью два года или более после заражения.');
