INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(885, 'ПОСЛЕДСТВИЯ ИНФЕКЦИОННЫХ И ПАРАЗИТАРНЫХ БОЛЕЗНЕЙ', 'B90-B94', 1, 'A00-B99', 4, 'Примечание: эти рубрики следует использовать для обозначения состояний, указанных в рубриках A00-B89, как причины последствий. Понятие "последствия" включает состояния, уточненные как таковые, а также остаточные явления заболеваний, классифицированных в упомянутых выше рубриках, если очевидно, что причинное заболевание в настоящее время отсутствует. При использовании этой категории следует руководствоваться рекомендациями и правилами кодирования заболеваемости и смертности, приведенными в т.2.');
