INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(1375, 'ЗЛОКАЧЕСТВЕННЫЕ НОВООБРАЗОВАНИЯ ЛИМФОИДНОЙ, КРОВЕТВОРНОЙ И РОДСТВЕННЫХ ИМ ТКАНЕЙ', 'C81-C96', 15057, 'C00-C97', 14, 'Примечание. Термины, используемые в рубриках С82-С85 для неходжкинских лимфом, представляют рабочую классификацию, в которой предприняты попытки найти общую основу нескольких главных классификационных схем. Термины, используемые в этих схемах, не даются в основном перечне рубрик, но представлены в Алфавитном указателе; полное отождествление с терминами основного перечня не всегда возможно.\nВключены: морфологические коды M959-M994 с кодом характера новообразования /3\nИсключены: вторичные и неуточненные новообразования лимфатических узлов (C77.-)');
