INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(1468, 'ЗЛОКАЧЕСТВЕННЫЕ НОВООБРАЗОВАНИЯ САМОСТОЯТЕЛЬНЫХ (ПЕРВИЧНЫХ) МНОЖЕСТВЕННЫХ ЛОКАЛИЗАЦИЙ', 'C97-C97', 15057, 'C00-C97', 1, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(1469, 'Злокачественное новообразование самостоятельных (первичных) множественных локализаций', 'C97', 1468, 'C97-C97', 0, 'Примечание. При использовании этой категории следует руководствоваться правилами кодирования смертности и рекомендациями, изложенными в ч. 2.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(1470, 'НОВООБРАЗОВАНИЯ IN SITU', 'D00-D09', 933, 'C00-D48', 9, 'Примечание. Многие новообразования in situ рассматриваются как последовательные морфологические изменения между дисплазией и инвазивным раком. Например, для цервикальной интраэпителиальной неоплазии (CIN) признаются три степени, из которых третья (CIN III) включает как выраженную дисплазию, так и карциному in situ. Эта система градаций распространена и на другие органы, например вульву и влагалище. Описание интраэпителиальной неоплазии III степени с указанием или без указания на тяжелую дисплазию представлены в этом разделе; градации I и II классифицируются как дисплазии вовлеченных систем органов и должны кодироваться по классам, соответствующим этим системам органов.\nВключены: болезнь Боуэна эритроплазия морфологические коды с кодом характера новообразования /2 эритроплазия Кейра');
