INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(1806, 'БОЛЕЗНИ КРОВИ, КРОВЕТВОРНЫХ ОРГАНОВ И ОТДЕЛЬНЫЕ НАРУШЕНИЯ, ВОВЛЕКАЮЩИЕ ИММУННЫЙ МЕХАНИЗМ', 'D50-D89', NULL, NULL, 6, 'Исключены: аутоиммунная болезнь (системная) БДУ (M35.9) отдельные состояния, возникающие в перинатальном периоде (P00-P96) осложнения беременности, родов и послеродового периода (O00-O99) врожденные аномалии, деформации и хромосомные нарушения (Q00-Q99) эндокринные болезни, расстройства питания и нарушения обмена веществ (E00-E90) болезнь, вызванная вирусом иммунодефицита человека [ВИЧ] (B20-B24) травмы, отравления и некоторые другие последствия воздействия внешних причин (S00-T98) новообразования (C00-D48) симптомы, признаки и отклонения от нормы, выявленные при клинических и лабораторных исследованиях, не классифицированные в других рубриках (R00-R99)\nЭтот класс содержит следующие блоки:\nD50-D53 Анемии, связанные с питанием\nD55-D59 Гемолитические анемии\nD60-D64 Апластические и другие анемии\nD65-D69 Нарушения свертываемости крови, пурпура и другие геморрагические состояния\nD70-D77 Другие болезни крови и кроветворных органов\nD80-D89 Отдельные нарушения, вовлекающие иммунный механизм\nЗвездочкой отмечены следующие категории:\nD63* Анемия при хронических болезнях, классифицированных в других рубриках\nD77* Другие нарушения крови и кроветворных органов при болезнях, классифицированных в других рубриках');
