INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2008, 'Нарушение, вовлекающее иммунный механизм, неуточненное', 'D89.9', 2003, 'D89', 0, 'Иммунная болезнь БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2009, 'БОЛЕЗНИ ЭНДОКРИННОЙ СИСТЕМЫ, РАССТРОЙСТВА ПИТАНИЯ И НАРУШЕНИЯ ОБМЕНА ВЕЩЕСТВ', 'E00-E90', NULL, NULL, 8, 'Примечание. Все новообразования (как функционально активные,так и неактивные) включены в класс II. Соответствующие коды в этом классе (например, Е05.8, Е07.0, Е16-Е31, Е34.-) при необходимости можно использовать в качестве дополнительных кодов для идентификации функционально активных новообразований и эктопической эндокринной ткани, а также гиперфункции и гипофункции эндокринных желез, связанных с новообразованиями и другими расстройствами, классифицированными в других рубриках.\nИсключены: осложнения беременности, родов и послеродового периода (О00-О99) симптомы, признаки и отклонения от нормы, выявленные при клинических и лабораторных исследованиях, не классифицированные в других рубриках (R00-R99) преходящие эндокринные нарушения и нарушения обмена веществ, специфичные для плода и новорожденного (Р70-Р74)\nЭтот класс содержит следующие блоки:\nЕ00-Е07 Болезни щитовидной железы\nЕ10-Е14 Сахарный диабет\nЕ15-Е16 Другие нарушения регуляции глюкозы и внутренней секреции поджелудочной железы\nЕ20-Е35 Нарушения других эндокринных желез\nЕ40-Е46 Недостаточность питания\nЕ50-Е64 Другие виды недостаточности питания\nЕ65-Е68 Ожирение и другие виды избыточности питания\nЕ70-Е90 Нарушения обмена веществ\nЗвездочкой обозначены следующие категории:\nЕ35* Нарушения эндокринных желез при болезнях, классифицированных в других рубриках\nЕ90 * Расстройства питания и нарушения обмена веществ при болезнях, классифицированных в других рубриках');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2010, 'БОЛЕЗНИ ЩИТОВИДНОЙ ЖЕЛЕЗЫ', 'E00-E07', 2009, 'E00-E90', 8, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2011, 'Синдром врожденной йодной недостаточности', 'E00', 2010, 'E00-E07', 4, 'Включены: эндемические состояния, связанные с дефицитом йода в окружающей природной среде как непосредственно, так и вследствие недостаточности йода в организме матери. Некоторые из этих состояний не могут считаться истинным гипотиреозом, а являются следствием неадекватной секреции тиреоидных гормонов у развивающегося плода; может существовать связь с природными зобогенными факторами. При необходимости идентифицировать сопутствущую задержку психического развития используют дополнительный код (F70-F79). Исключен: субклинический гипотиреоз вследствие йодной недостаточности (E02)');
