INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2013, 'Синдром врожденной йодной недостаточности, микседематозная форма', 'E00.1', 2011, 'E00', 0, 'Эндемический кретинизм: . гипотиреоидный . микседематозная форма');
