INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2216, 'НЕДОСТАТОЧНОСТЬ ПИТАНИЯ', 'E40-E46', 2009, 'E00-E90', 7, 'Примечание. Степень недостаточности питания обычно оценивают по показателям массы тела, выраженным в стандартных отклонениях от средней величины для эталонной популяции. Отсутствие прибавки массы тела у детей или свидетельство снижения массы тела у детей или взрослых при наличии одного или более предыдущих измерений массы тела обычно является индикатором недостаточности питания. При наличии показателей только однократного измерения массы тела диагноз основывается на предположениях и не считается окончательным, если не проведены другие клинические и лабораторные исследования. В исключительных случаях, когда отсутствуют какие-либо сведения о массе тела, за основу берутся клинические данные. Если масса тела индивида ниже среднего показателя для эталонной популяции, то тяжелую недостаточность питания с высокой степенью вероятности можно предположить тогда, когда наблюдаемое значение на 3 или более стандартных отклонений ниже среднего значения для эталонной группы; недостаточность питания средней степени, если наблюдаемая величина на 2 или более, но менее чем на 3 стандартных отклонений ниже средней величины, и легкую степень недостаточности питания, если наблюдаемый показатель массы тела на 1 или более, но менее чем на 2 стандпртных отклонения ниже среднего значения для эталонной группы.\nИсключены: нарушение всасывания в кишечнике (K90.-) алиментарная анемия (D50-D53) последствия белково-энергетической недостаточности (E64.0) истощающая болезнь (B22.2) голодание (T73.0)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2217, 'Квашиоркор', 'E40', 2216, 'E40-E46', 0, 'Тяжелое нарушение питания, сопровождаемое алиментарными отеками и нарушениями пигментации кожи и волос Исключен: маразматический квашиоркор (E42)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2218, 'Алиментарный маразм', 'E41', 2216, 'E40-E46', 0, 'Тяжелое нарушение питания, сопровождающееся маразмом Исключен: маразматический квашиоркор (E42)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2219, 'Маразматический квашиоркор', 'E42', 2216, 'E40-E46', 0, 'Тяжелая белково-энергетическая недостаточность [как в Е43]: . промежуточная форма . с симптомами квашиоркора и маразма');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2220, 'Тяжелая белково-энергетическая недостаточность неуточненная', 'E43', 2216, 'E40-E46', 0, 'Тяжелая потеря массы тела у детей или взрослых или отсутствие прибавки массы тела у ребенка, которые приводят к тому, что выявляемая масса тела оказывается как минимум на 3 стандартных отклонения ниже среднего показателя для эталонной группы (или подобное снижение массы тела, отраженное другими статистическими методами). Если в распоряжении имеются данные лишь однократного измерения массы тела, то о тяжелом истощении с большой степенью вероятности можно говорить, когда выявленная масса тела на 3 или более стандартных отклонений ниже среднего показателя для эталонной группы населения. Голодный отек');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2221, 'Белково-энергетическая недостаточность умеренной и слабой степени', 'E44', 2216, 'E40-E46', 2, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2222, 'Умеренная белково-энергетическая недостаточность', 'E44.0', 2221, 'E44', 0, 'Потеря массы тела у детей или взрослых или отсутствие прибавки массы тела у ребенка, которые приводят к тому, что выявляемая масса тела оказывается ниже среднего показателя для эталонной группы населения на 2 стандартных отклонения или более, но менее чем на 3 стандартных отклонения (или подобное снижение массы тела, отраженное другими статистическими методами). Если в распоряжении имеются данные лишь однократного измерения массы тела, то об умеренной белково-энергетической недостаточности с большой степенью вероятности можно говорить, когда выявляемая масса тела на 2 или более стандартных отклонений ниже среднего показателя для эталонной группы населения.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2223, 'Легкая белково-энергетическая недостаточность', 'E44.1', 2221, 'E44', 0, 'Потеря массы тела у детей или взрослых или отсутствие прибавки массы тела у ребенка, которые приводят к тому, что выявляемая масса тела оказывается ниже среднего показателя для эталонной группы населения на 1 или более, но менее чем на 2 стандартных отклонения (или подобное снижение массы тела, отраженное другими статистическими методами). Если в распоряжении имеются данные лишь однократного измерения массы тела, то о легкой белково-энергетической недостаточности с большой степенью вероятности можно говорить, когда выявляенная масса тела на 1 или более, но менее чем на 2 стандартных отклонения ниже среднего показателя для эталонной группы населения.');
