INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2498, 'Психическое расстройство и расстройство поведения, вызванное употреблением опиоидов, неуточненное', 'F11.9', 2487, 'F11', 0, NULL);
