INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2521, 'Психическое расстройство и расстройство поведения, вызванное употреблением седативных или снотворных средств, неуточненное', 'F13.9', 2511, 'F13', 0, NULL);
