INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2567, 'Резидуальные и отсроченные психотические расстройства, вызванные употреблением табака', 'F17.7', 2558, 'F17', 0, 'Расстройство, при котором нарушения познавательных функций, эмоций, личности или поведения, вызванные приемом алкоголя или психоактивного вещества, могут сохраняться после периода, в течение которого проявляется непосредственное влияние психоактивного вещества. Начало расстройства должно быть непосредственно связано с употреблением психоактивного вещества. Случаи, при которых нарушения возникают после эпизода (эпизодов) употребления психоактивного вещества, должны кодироваться вышеуказанным четвертым знаком только тогда, когда есть убедительные доказательства причастности остаточных явлений воздействия психоактивного вещества к расстройству. Резидуальные явления можно отличить от психотического состояния отчасти по их эпизодичности, преимущественно очень короткой продолжительности, дублированию предшествующих алкогольных или наркотических проявлений. Алкогольная деменция БДУ Хронический алкогольный церебральный синдром Деменция и другие легкие формы стойких нарушений познавательных функций "Флэшбэк" Отсроченное психотическое расстройство, вызванное употреблением психоактивного вещества Нарушение восприятия после употребления галлюциногена Резидуальное: . эмоциональное [аффективное] расстройство . расстройство личности и поведения Исключены: алкогольный или наркотический: . корсаковский синдром (F10-F19 с общим четвертым знаком .6) . психотическое состояние (F10-F19 с общим четвертым знаком .5)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2568, 'Другие психические расстройства и расстройства поведения, вызванные употреблением табака', 'F17.8', 2558, 'F17', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2569, 'Психическое расстройство и расстройство поведения, вызванное употреблением табака, неуточненное', 'F17.9', 2558, 'F17', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2570, 'Психические и поведенческие расстройства, вызванные употреблением летучих растворителей', 'F18', 2474, 'F10-F19', 10, '[четырехзначные подрубрики см. выше]');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2572, 'Психические и поведенческие расстройства, вызванные употреблением летучих растворителей. Острая интоксикация', 'F18.0', 2570, 'F18', 0, 'Состояние, вызванное применением психоактивного вещества, проявляющееся в нарушениях сознания, познавательной способности, восприятия, эмоций и поведения или других психофизиологических функций и реакций. Эти нарушения непосредственно связаны с острым фармакологическим действием вещества и через некоторое время полностью исчезают, за исключением случаев, когда имеют место повреждения тканей и другие осложнения. В числе осложнений могут быть травма, аспирация рвотных масс, делирий, кома, судороги. Характер осложнений зависит от фармакологического класса вещества и способа его введения. Острое опьянение при алкоголизме Bad trips (наркотическое опьянение) Алкогольное опьянение БДУ Патологическая интоксикация Расстройства в виде транса и одержимости при интоксикации, вызванной психоактивными веществами');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2573, 'Психические и поведенческие расстройства, вызванные употреблением летучих растворителей. Пагубное употребление', 'F18.1', 2570, 'F18', 0, 'Сам способ употребления психоактивного вещества является причиной ущерба здоровью. Ущерб может быть физическим (как, например, случаи гепатита, вызванного самостоятельными инъекциями психоактивных веществ) или психическим (как, например, эпизоды депрессивного расстройства, вторичного по отношению к тяжелому алкогольному опьянению). Злоупотребление психоактивным веществом');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2574, 'Психические и поведенческие расстройства, вызванные употреблением летучих растворителей. Синдром зависимости', 'F18.2', 2570, 'F18', 0, 'Комплекс поведенческих, познавательных и физиологических симптомов, который возникает после повторного использования вещества и обычно включает сильное желание принять его; трудности в контролировании его употребления; упорное продолжение его использования, несмотря на пагубные последствия; предпочтение употребления психоактивного вещества в ущерб другим видам деятельности и выполнению обязанностей; возрастание допустимых пределов употребления и иногда состояние абстиненции. Синдром зависимости может быть по отношению к определенному веществу (например, табаку, алкоголю или диазепаму), классу веществ (например, опиоидным наркотикам) или к широкому ряду фармакологически различных психоактивных веществ. Хронический алкоголизм Дипсомания Наркомания');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2575, 'Психические и поведенческие расстройства, вызванные употреблением летучих растворителей. Абстинентное состояние', 'F18.3', 2570, 'F18', 0, 'Группа симптомов различного характера и различной тяжести, возникающих в результате полного или частичного удаления из организма психоактивного вещества после постоянного употребления. Время начала и продолжительность абстинентного состояния зависят от типа психоактивного вещества и его дозы, принятой непосредственно перед прекращением или уменьшением дозы приема. Абстинентное состояние может осложняться судорогами.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2576, 'Психические и поведенческие расстройства, вызванные употреблением летучих растворителей. Абстинентное состояние с делирием', 'F18.4', 2570, 'F18', 0, 'Состояние, при котором абстиненция, охарактеризованная выше (общий четвертый знак .3), осложнена делирием, охарактеризованным в рубрике F05.-. Это состояние может также сопровождаться судорогами. Если в этиологии расстройства играет роль органический фактор, такое состояние следует классифицировать рубрикой F05.8. Белая горячка (алкогольная)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2577, 'Психические и поведенческие расстройства, вызванные употреблением летучих растворителей. Психотическое расстройство', 'F18.5', 2570, 'F18', 0, 'Комплекс психотических симптомов, возникающих во время или после употребления психоактивного вещества, которые, однако, не могут быть объяснены только острой интоксикацией и которые не являются составной частью абстинентного состояния. Расстройство характеризуется галлюцинациями (обычно слуховыми, но часто и нескольких видов), расстройствами восприятия, бредом (часто параноидного характера или мании преследования), психомоторными расстройствами (возбуждением или ступором), ненормальной аффектацией, колеблющейся от сильного страха до экстаза. Сознание обычно ясное, однако может иметь место некоторая степень его помрачения, но без тяжелой спутанности. Алкогольный(ая): . галлюциноз . бред ревности . паранойя . психоз БДУ Исключены: алкогольные или вызванные употреблением другого психоактивного вещества резидуальные и отсроченные психотические расстройства (F10-F19 с общим четвертым знаком .7)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2578, 'Психические и поведенческие расстройства, вызванные употреблением летучих растворителей. Амнестический синдром', 'F18.6', 2570, 'F18', 0, 'Синдром, характеризующийся выраженным хроническим снижением памяти на недавние и отдаленные события. Непосредственное воскрешение в памяти событий обычно не нарушено. Память на недавние события обычно нарушена сильнее, чем на отдаленные. Обычно явно выражено нарушение ощущения времени и последовательности событий и имеются трудности в освоении нового материала. Конфабуляция возможна, но не обязательна. Другие познавательные функции обычно относительно хорошо сохранены, и амнестические расстройства непропорциональны выраженности других нарушений. Амнестическое расстройство, обусловленное алкоголем или наркотиком Корсаковский психоз или синдром, обусловленный алкоголем или другим психоактивным веществом или неуточненный Исключен: неалкогольный корсаковский психоз или синдром (F04)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2579, 'Резидуальные и отсроченные психотические расстройства, вызванные употреблением летучих растворителей', 'F18.7', 2570, 'F18', 0, 'Расстройство, при котором нарушения познавательных функций, эмоций, личности или поведения, вызванные приемом алкоголя или психоактивного вещества, могут сохраняться после периода, в течение которого проявляется непосредственное влияние психоактивного вещества. Начало расстройства должно быть непосредственно связано с употреблением психоактивного вещества. Случаи, при которых нарушения возникают после эпизода (эпизодов) употребления психоактивного вещества, должны кодироваться вышеуказанным четвертым знаком только тогда, когда есть убедительные доказательства причастности остаточных явлений воздействия психоактивного вещества к расстройству. Резидуальные явления можно отличить от психотического состояния отчасти по их эпизодичности, преимущественно очень короткой продолжительности, дублированию предшествующих алкогольных или наркотических проявлений. Алкогольная деменция БДУ Хронический алкогольный церебральный синдром Деменция и другие легкие формы стойких нарушений познавательных функций "Флэшбэк" Отсроченное психотическое расстройство, вызванное употреблением психоактивного вещества Нарушение восприятия после употребления галлюциногена Резидуальное: . эмоциональное [аффективное] расстройство . расстройство личности и поведения Исключены: алкогольный или наркотический: . корсаковский синдром (F10-F19 с общим четвертым знаком .6) . психотическое состояние (F10-F19 с общим четвертым знаком .5)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2580, 'Другие психические расстройства и расстройства поведения, вызванные употреблением летучих растворителей', 'F18.8', 2570, 'F18', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2581, 'Психическое расстройство и расстройство поведения, вызванное употреблением летучих растворителей, неуточненное', 'F18.9', 2570, 'F18', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2582, 'Психические и поведенческие расстройства, вызванные одновременным употреблением нескольких наркотических средств и использованием других психоактивных веществ', 'F19', 2474, 'F10-F19', 10, '[четырехзначные подрубрики см. выше] Эту рубрику следует использовать, если известно об употреблении двух или более психоактивных веществ, но невозможно установить, какое из них в большей степени ответственно за возникшее расстройство. Эту рубрику также следует использовать, когда индентификация некоторых или даже всех применявшихся психоактивных веществ затруднительна, так как многие лица, потребляющие несколько наркотиков, сами часто не знают точно, что они принимают. Включено: злоупотребление наркотиками БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2584, 'Психические и поведенческие расстройства, вызванные одновременным употреблением нескольких наркотических средств и использованием других психоактивных веществ. Острая интоксикация', 'F19.0', 2582, 'F19', 0, 'Состояние, вызванное применением психоактивного вещества, проявляющееся в нарушениях сознания, познавательной способности, восприятия, эмоций и поведения или других психофизиологических функций и реакций. Эти нарушения непосредственно связаны с острым фармакологическим действием вещества и через некоторое время полностью исчезают, за исключением случаев, когда имеют место повреждения тканей и другие осложнения. В числе осложнений могут быть травма, аспирация рвотных масс, делирий, кома, судороги. Характер осложнений зависит от фармакологического класса вещества и способа его введения. Острое опьянение при алкоголизме Bad trips (наркотическое опьянение) Алкогольное опьянение БДУ Патологическая интоксикация Расстройства в виде транса и одержимости при интоксикации, вызванной психоактивными веществами');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2585, 'Психические и поведенческие расстройства, вызванные одновременным употреблением нескольких наркотических средств и использованием других психоактивных веществ. Пагубное употребление', 'F19.1', 2582, 'F19', 0, 'Сам способ употребления психоактивного вещества является причиной ущерба здоровью. Ущерб может быть физическим (как, например, случаи гепатита, вызванного самостоятельными инъекциями психоактивных веществ) или психическим (как, например, эпизоды депрессивного расстройства, вторичного по отношению к тяжелому алкогольному опьянению). Злоупотребление психоактивным веществом');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2586, 'Психические и поведенческие расстройства, вызванные одновременным употреблением нескольких наркотических средств и использованием других психоактивных веществ. Синдром зависимости', 'F19.2', 2582, 'F19', 0, 'Комплекс поведенческих, познавательных и физиологических симптомов, который возникает после повторного использования вещества и обычно включает сильное желание принять его; трудности в контролировании его употребления; упорное продолжение его использования, несмотря на пагубные последствия; предпочтение употребления психоактивного вещества в ущерб другим видам деятельности и выполнению обязанностей; возрастание допустимых пределов употребления и иногда состояние абстиненции. Синдром зависимости может быть по отношению к определенному веществу (например, табаку, алкоголю или диазепаму), классу веществ (например, опиоидным наркотикам) или к широкому ряду фармакологически различных психоактивных веществ. Хронический алкоголизм Дипсомания Наркомания');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2587, 'Психические и поведенческие расстройства, вызванные одновременным употреблением нескольких наркотических средств и использованием других психоактивных веществ. Абстинентное состояние', 'F19.3', 2582, 'F19', 0, 'Группа симптомов различного характера и различной тяжести, возникающих в результате полного или частичного удаления из организма психоактивного вещества после постоянного употребления. Время начала и продолжительность абстинентного состояния зависят от типа психоактивного вещества и его дозы, принятой непосредственно перед прекращением или уменьшением дозы приема. Абстинентное состояние может осложняться судорогами.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2588, 'Психические и поведенческие расстройства, вызванные одновременным употреблением нескольких наркотических средств и использованием других психоактивных веществ. Абстинентное состояние с делирием', 'F19.4', 2582, 'F19', 0, 'Состояние, при котором абстиненция, охарактеризованная выше (общий четвертый знак .3), осложнена делирием, охарактеризованным в рубрике F05.-. Это состояние может также сопровождаться судорогами. Если в этиологии расстройства играет роль органический фактор, такое состояние следует классифицировать рубрикой F05.8. Белая горячка (алкогольная)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2589, 'Психические и поведенческие расстройства, вызванные одновременным употреблением нескольких наркотических средств и использованием других психоактивных веществ. Психотическое расстройство', 'F19.5', 2582, 'F19', 0, 'Комплекс психотических симптомов, возникающих во время или после употребления психоактивного вещества, которые, однако, не могут быть объяснены только острой интоксикацией и которые не являются составной частью абстинентного состояния. Расстройство характеризуется галлюцинациями (обычно слуховыми, но часто и нескольких видов), расстройствами восприятия, бредом (часто параноидного характера или мании преследования), психомоторными расстройствами (возбуждением или ступором), ненормальной аффектацией, колеблющейся от сильного страха до экстаза. Сознание обычно ясное, однако может иметь место некоторая степень его помрачения, но без тяжелой спутанности. Алкогольный(ая): . галлюциноз . бред ревности . паранойя . психоз БДУ Исключены: алкогольные или вызванные употреблением другого психоактивного вещества резидуальные и отсроченные психотические расстройства (F10-F19 с общим четвертым знаком .7)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2590, 'Психические и поведенческие расстройства, вызванные одновременным употреблением нескольких наркотических средств и использованием других психоактивных веществ. Амнестический синдром', 'F19.6', 2582, 'F19', 0, 'Синдром, характеризующийся выраженным хроническим снижением памяти на недавние и отдаленные события. Непосредственное воскрешение в памяти событий обычно не нарушено. Память на недавние события обычно нарушена сильнее, чем на отдаленные. Обычно явно выражено нарушение ощущения времени и последовательности событий и имеются трудности в освоении нового материала. Конфабуляция возможна, но не обязательна. Другие познавательные функции обычно относительно хорошо сохранены, и амнестические расстройства непропорциональны выраженности других нарушений. Амнестическое расстройство, обусловленное алкоголем или наркотиком Корсаковский психоз или синдром, обусловленный алкоголем или другим психоактивным веществом или неуточненный Исключен: неалкогольный корсаковский психоз или синдром (F04)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2591, 'Резидуальные и отсроченные психотические расстройства, вызванные одновременным употреблением нескольких наркотических средств и использованием других психоактивных веществ', 'F19.7', 2582, 'F19', 0, 'Расстройство, при котором нарушения познавательных функций, эмоций, личности или поведения, вызванные приемом алкоголя или психоактивного вещества, могут сохраняться после периода, в течение которого проявляется непосредственное влияние психоактивного вещества. Начало расстройства должно быть непосредственно связано с употреблением психоактивного вещества. Случаи, при которых нарушения возникают после эпизода (эпизодов) употребления психоактивного вещества, должны кодироваться вышеуказанным четвертым знаком только тогда, когда есть убедительные доказательства причастности остаточных явлений воздействия психоактивного вещества к расстройству. Резидуальные явления можно отличить от психотического состояния отчасти по их эпизодичности, преимущественно очень короткой продолжительности, дублированию предшествующих алкогольных или наркотических проявлений. Алкогольная деменция БДУ Хронический алкогольный церебральный синдром Деменция и другие легкие формы стойких нарушений познавательных функций "Флэшбэк" Отсроченное психотическое расстройство, вызванное употреблением психоактивного вещества Нарушение восприятия после употребления галлюциногена Резидуальное: . эмоциональное [аффективное] расстройство . расстройство личности и поведения Исключены: алкогольный или наркотический: . корсаковский синдром (F10-F19 с общим четвертым знаком .6) . психотическое состояние (F10-F19 с общим четвертым знаком .5)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2592, 'Другие психические расстройства и расстройства поведения, вызванные одновременным употреблением нескольких наркотических средств и использованием других психоактивных веществ', 'F19.8', 2582, 'F19', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2593, 'Психическое расстройство и расстройство поведения, вызванное одновременным употреблением нескольких наркотических средств и использованием других психоактивных веществ, неуточненное', 'F19.9', 2582, 'F19', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2594, 'ШИЗОФРЕНИЯ, ШИЗОТИПИЧЕСКИЕ И БРЕДОВЫЕ РАССТРОЙСТВА', 'F20-F29', 2428, 'F00-F99', 8, 'Этот блок включает в себя шизофрению как наиболее важную составную\nчасть группы, шизотипическое расстройство, устойчивые бредовые рас-\nстройства и большую группу острых и преходящих психотических рас-\nстройств. Шизоаффективные расстройства были оставлены в этом блоке,\nнесмотря на их противоречивый характер.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2595, 'Шизофрения', 'F20', 2594, 'F20-F29', 9, 'Шизофренические расстройства обычно характеризуются существенными и характерными искажениями мышления и восприятия, а также неадекватными аффектами. Ясное сознание и интеллектуальные способности обычно сохраняются, хотя с течением времени может иметь место определенное снижение познавательных способностей. Важнейшая психопатологическая симптоматика включает ощущение отражения мыслей (эхо), вкладывания чужой или похищения собственной мысли, передачи мысли на расстояние; бредовое восприятие и бред контроля извне; инертность; слуховые галлюцинации, комментирующие или обсуждающие больного в третьем лице; беспорядочность мысли и симптомы негативизма. Течение шизофренических расстройств может быть продолжительным или эпизодическим с прогрессированием или стабильностью нарушений; это может быть один или несколько эпизодов болезни с полной или неполной ремиссией. При наличии обширной депрессивной или маниакальной симптоматики диагноз шизофрении не следует ставить до тех пор, пока не будет ясно, что шизофреническая симптоматика предшествовала аффективным нарушениям. Не следует диагностировать шизофрению и при наличии очевидной болезни мозга, а также в течение наркотической интоксикации или абстиненции. Аналогичные расстройства, развивающиеся при эпилепсии или других болезнях головного мозга, следует кодировать рубрикой F06.2, а если их возникновение связано с употреблением психоактивных веществ, - рубриками F10-F19 с общим четвертым знаком .5. Исключены: шизофрения: . острая (недифференцированная) (F23.2) . циклическая (F25.2) шизофреническая реакция (F23.2) шизотипическое расстройство (F21)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2596, 'Параноидная шизофрения', 'F20.0', 2595, 'F20', 0, 'Параноидная форма шизофрении, при которой в клинической картине доминируют относительно устойчивый, часто параноидный бред, обычно сопровождающийся галлюцинациями, особенно слуховыми, и расстройства восприятия. Расстройства эмоций, воли, речи и кататонические симптомы отсутчтвуют или относительно слабо выражены. Парафреническая шизофрения Исключены: инволюционное параноидное состояние (F22.8) паранойя (F22.0)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2597, 'Гебефреническая шизофрения', 'F20.1', 2595, 'F20', 0, 'Форма шизофрении, при которой доминируют аффективные изменения. Бред и галлюцинации поверхностны и фрагментарны, поведение нелепо и непредсказуемо, обычно манерничанье. Настроение изменчиво и неадекватно, мышление дезорганизовано, речь бессвязна. Имеется тенденция к социальной изоляции. Прогноз обычно неблагоприятен вследствие быстрого нарастания "негативных" симптомов, особенно аффективного уплощения и потери воли. Гебефрению следует диагностировать только в подростковом и юношеском возрасте. Дезорганизованная шизофрения Гебефрения');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2598, 'Кататоническая шизофрения', 'F20.2', 2595, 'F20', 0, 'В клинической картине кататонической шизофрении доминируют чередующиеся психомоторные нарушения полярного характера, такие, как колебания между гиперкинезом и ступором или автоматическим подчинением и негативизмом. Скованные позы могут сохраняться в течение длительного времени. Примечательной особенностью состояния могут быть случаи резкого возбуждения. Кататонические проявления могут сочетаться со сноподобным (онейроидным) состоянием с яркими сценическими галлюцинациями. Кататонический ступор Шизофреническая: . каталепсия . кататония . восковая гибкость');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2599, 'Недифференцированная шизофрения', 'F20.3', 2595, 'F20', 0, 'Психотическое состояние, отвечающее основным диагностическим критериям шизофрении, но не соответствующее какой-либо ее форме, классифицированной в подрубриках F20.0-F20.2, или проявляющее черты более чем одной из вышеуказанных форм без ярко выраженного преобладания специфического комплекса диагностических характеристик. Антипичная шизофрения Исключены: острое шизофреноподобное психотическое расстройство (F23.2) хроническая недифференцированная шизофрения (F20.5) постшизофреническая депрессия (F20.4)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2600, 'Постшизофреническая депрессия', 'F20.4', 2595, 'F20', 0, 'Депрессивный эпизод, который может быть длительным, возникающий как последствие заболевания шизофренией. Некоторые симптомы шизофрении ("позитивные" или "негативные") все еще должны присутствовать, но они уже не доминируют в клинической картине. С этими депрессивными состояниями связан повышенный риск самоубийства. Если у пациента уже не обнаруживаются какие-либо симптомы шизофрении, следует ставить диагноз депрессивного эпизода (F32.-). Если симптомы шизофрении все еще ярки и четки, следует ставить диагноз соответствующего типа шизофрении (F20.0-F20.3).');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2601, 'Остаточная шизофрения', 'F20.5', 2595, 'F20', 0, 'Хроническая стадия в развитии заболевания шизофренией, при которой имел место явный переход от ранней стадии к поздней стадии, характеризующейся длительными (хотя и не обязательно необратимыми) "негативными" симптомами, такими, как психомоторная заторможенность; низкая активность; эмоциональная притупленность; пассивность и недостаток инициативы; бедность содержания речи; бедность невербальных взаимодействий посредством мимики, выражения глаз, интонаций и поз; снижение заботы о себе и скудность социальных действий. Хроническая недифференцированная шизофрения Резидуальное шизофреническое состояние');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2602, 'Простой тип шизофрении', 'F20.6', 2595, 'F20', 0, 'Расстройство, при котором наблюдается незаметное, но прогрессирующее развитие странностей в поведении, неспособности удовлетворять требованиям общества и снижение всех видов деятельности. Характерные негативные черты остаточной шизофрении (например, уплощение аффекта и потеря воли) развиваются без каких-либо явных предшествующих психотических симптомов.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2603, 'Другой тип шизофрении', 'F20.8', 2595, 'F20', 0, 'Сенестопатическая шизофрения Шизофреноформное(ый): . расстройство БДУ . психоз БДУ Исключено: краткое шизофреноформное расстройство (F23.2)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2604, 'Шизофрения неуточненная', 'F20.9', 2595, 'F20', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2605, 'Шизотипическое расстройство', 'F21', 2594, 'F20-F29', 0, 'Расстройство, характеризующееся эксцентричным поведением, аномалиями мышления и эмоциональных реакций, похожими на те, которые имеют место при шизофрении, однако отчетливые и характерные для шизофрении нарушения не обнаруживаются ни на какой стадии болезни. Симптомы могут включать холодность или неадекватность эмоциональных реакций, странное или эксцентричное поведение, склонность к социальной изоляции, параноидные или необычные идеи, не доходящие до явно выраженного бреда, болезненную навязчивость, нарушение мышления и расстройства восприятия, редкие преходящие квазипсихотические эпизоды с выраженными иллюзорными ощущениями, слуховыми или другими галлюцинациями, бредовыми идеями, обычно возникающими без видимых причин. Отсутствует определенность начала болезни и ее развития, а ее течение обычно такое же, как и при расстройстве личности. Латентная шизофреническая реакция Шизофрения: . пограничная . латентная . предпсихотическая . продромальная . псевдоневротическая . псевдопсихопатическая Шизотипическое расстройство личности Исключены: синдром Аспергера (F84.5) шизоидное расстройство личности (F60.1)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2606, 'Хронические бредовые расстройства', 'F22', 2594, 'F20-F29', 3, 'Включают ряд расстройств, при которых устойчивый бред является единственным или наиболее характерным клиническим симптомом и которые не могут быть классифицированы как органические, шизофренические или аффективные. Бредовые расстройства, которые длились менее нескольких месяцев, следует обозначать, хотя бы временно, рубрикой F23.-.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2607, 'Бредовое расстройство', 'F22.0', 2606, 'F22', 0, 'Расстройство, характеризующннся развитием единственной картины бреда или серии связанных картин бреда, которые обычно устойчивы и иногда пожизненны. Содержание бреда или серии картин бреда чрезвычайно вариабельно. Совершенно несовместимыми с этим диагнозом являются четкие и устойчивые слуховые галлюцинации (голоса), шизофренические симптомы, такие, как бред контроля извне, и выраженная эмоциональная притупленность, а также явные признаки заболевания мозга. Однако наличие случайных или преходящих слуховых галлюцинаций, особенно у больных пожилого возраста, не исключает настоящего диагноза при условии, что они не являются типично шизофреническими и составляют только небольшую часть общей клинической картины. Паранойя Параноидный(ое): . психоз . состояние Парафрения (поздняя) Сенситивный бред отношения Исключены: параноидное(ый)(ая): . расстройство личности (F60.0) . психоз психогенный (F23.3) . реакция (F23.3) . шизофрения (F20.0)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2608, 'Другие хронические бредовые расстройства', 'F22.8', 2606, 'F22', 0, 'Расстройства, при которых одна или несколько картин бреда сопровождаются устойчивыми галлюцинаторными голосами или шизофреническими симптомами, которые не укладываются в диагноз шизофрении (F20.-). Бредовая дисморфофобия Инволюционное параноидное состояние Кверулянтная паранойя');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2609, 'Хроническое бредовое расстройство неуточненное', 'F22.9', 2606, 'F22', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2610, 'Острые и преходящие психотические расстройства', 'F23', 2594, 'F20-F29', 6, 'Разнородная группа нарушений, характеризующихся острым началом психотических симптомов, таких, как бред, галлюцинации и расстройства восприятия, и тяжелым нарушением обычного поведения. Под острым началом понимают быстро нарастающее развитие (в течение двух недель или менее) ясно выраженной аномальной клинической картины. Очевидная органическая причина этих нарушений отсутствует. Часто отмечаются растерянность и недоумение, но дезориентация во времени, месте и окружении не настолько устойчива и тяжела, чтобы можно было диагностировать делирий органической этиологии (F05.-). Полное выздоровление обычно наступает в течение нескольких месяцев, часто в течение нескольких недель или даже дней. Если эти нарушения принимают устойчивый характер, необходимо будет изменить классификационную рубрику этого состояния. Описанное расстройство может быть связано (не всегда) с острым стрессом, под которым понимают стрессовые ситуации, имевшие место за одну-две недели до начала расстройства.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2611, 'Острое полиморфное психотическое расстройство без симптомов шизофрении', 'F23.0', 2610, 'F23', 0, 'симптомов шизофрении Острое психотическое расстройство, при котором галлюцинации, бред или расстройство восприятия несомненны, но чрезвычайно многообразны, изменяясь день ото дня или даже час от часу. Кроме того, часто имеет место эмоциональная неустойчивость с выраженными преходящими ощущениями счастья, экстаза или беспокойства, раздражительности. Полиморфизм и нестабильность характерны для всей клинической картины, и психотические признаки не подтверждают диагноз шизофрении (F20.-). Эти расстройства часто внезапно начинаются, быстро (в течение нескольких дней) развиваются и нередко столь же быстро угасают, не повторяясь в последующем. Если вышеуказанная симптоматика устойчива, диагноз следует изменить на хроническое бредовое расстройство (F22.-). Острый бред без симптомов шизофрении или неуточненный Циклоидный психоз без симптомов шизофрении или неуточненный');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2612, 'Острое полиморфное психотическое расстройство с симптомами шизофрении', 'F23.1', 2610, 'F23', 0, 'Острое психотическое расстройство с полиморфной и неустойчивой клинической картиной, описанной в подрубрике F23.0; однако, несмотря на эту нестабильность, в большинстве случаев присутствует ряд симптомов шизофрении. Если шизофреническая симптоматика устойчива, диагноз должен быть изменен на шизофрению (F20.-). Острый бред с симптомами шизофрении Циклоидный психоз с симптомами шизофрении');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2613, 'Острое шизофреноформное психотическое расстройство', 'F23.2', 2610, 'F23', 0, 'Острое психотическое оасстройство, при котором психотические симптомы относительно стабильны и соответствуют диагнозу шизофрении, но сохраняются до одного месяца. Полиморфные неустойчивые черты, описанные в подрубрике F23.0, отсутствуют. Если шизофреническая симптоматика устойчива, диагноз следует изменить на шизофрению (F20.-). Острая (недифференцированная) шизофрения Краткий(ое) шизофреноформный(ое): . психоз . расстройство Онейрофрения Шизофреническая реакция Исключены: органическое бредовое [шизофреноподобное] расстройство (F06.2) шизофреноформное расстройство БДУ (F20.8)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2614, 'Другие острые преимущественно бредовые психотические расстройства', 'F23.3', 2610, 'F23', 0, 'Острые психотические расстройства, при которых основными клиническими чертами являются относительно стабильный бред или галлюцинации, однако не позволяющие диагностировать шизофрению (F20.-). Если бред устойчив, диагноз следует изменить на хроническое бредовое расстройство (F22.-). Параноидная реакция Психогенный параноидный психоз');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2615, 'Другие острые и преходящие психотические расстройства', 'F23.8', 2610, 'F23', 0, 'Любые другие уточненные острые психотические расстройства, не имеющие очевидной органической причины возникновения, которые невозможно отнести к рубрикам F23.0-F23.3.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2616, 'Острое и преходящее психотическое расстройство неуточненное', 'F23.9', 2610, 'F23', 0, 'Краткий реактивный психоз БДУ Реактивный психоз');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2617, 'Индуцированное бредовое расстройство', 'F24', 2594, 'F20-F29', 0, 'Бредовое расстройство, общее для двух или более лиц, находящихся в тесном эмоциональном контакте. Только один из них страдает истинным психотическим расстройством; бред передается путем индукции другому лицу (или другим лицам) и обычно исчезает при прекращении контакта с больным. Folie a deux Индуцированное: . параноидное расстройство . психотическое расстройство');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2618, 'Шизоаффективные расстройства', 'F25', 2594, 'F20-F29', 5, 'Эпизодические расстройства, при которых одинаково ярко проявляется шизофреническая и маниакальная симптоматика, на основании которой невозможно поставить диагноз только шизофрении либо только депрессивного или маниакального эпизода. Другие состояния, при которых аффективные симптомы накладываются на уже имеющуюся шизофрению, сосуществуют или чередуются с другими видами хронических бредовых расстройств, классифицируются рубриками F20-F29. Психотическая симптоматика в виде выраженных нарушений настроения при аффективных расстройствах не дает основания для диагностирования шизоаффективного расстройства.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2619, 'Шизоаффективное расстройство, маниакальный тип', 'F25.0', 2618, 'F25', 0, 'Расстройство, при котором и шизофренические, и маниакальные симптомы настолько выражены, что невозможно поставить диагноз ни шизофрении, ни маниакального эпизода. Эту рубрику следует использовать как для одиночного эпизода, так и для рецидивирующего расстройства, при котором большинство эпизодов являются шизоаффективными, маниакального типа. Шизоаффективный психоз, маниакальный тип Шизофреноформный психоз, маниакальный тип');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2620, 'Шизоаффективное расстройство, депрессивный тип', 'F25.1', 2618, 'F25', 0, 'Расстройство, при котором и шизофренические, и депрессивные симптомы настолько выражены, что невозможно поставить диагноз ни шизофрении, ни депрессивного эпизода. Эту рубрику следует использовать и для одиночного эпизода, и для рецидивирующего расстройства, при котором большинство эпизодов являются шизоаффективными, депрессивного типа. Шизоаффективный психоз, депрессивный тип Шизофреноформный психоз, депрессивный тип');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2621, 'Шизоаффективное расстройство, смешанный тип', 'F25.2', 2618, 'F25', 0, 'Циклическая шизофрения Смешанный шизофренический и аффективный психоз');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2622, 'Другие шизоаффективные расстройства', 'F25.8', 2618, 'F25', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2623, 'Шизоаффективное расстройство неуточненное', 'F25.9', 2618, 'F25', 0, 'Шизоаффективный психоз БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2624, 'Другие неорганические психотические расстройства', 'F28', 2594, 'F20-F29', 0, 'Бредовые или галлюцинаторные расстройства, не дающие основания для постановки диагноза шизофрении (F20.-), хронических бредовых расстройств (F22.-), острых и преходящих психотических расстройств (F23.-), психотических типов маниакального эпизода (F30.2) или тяжелого депрессивного эпизода (F32.3). Хронический галлюцинаторный психоз');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2625, 'Неорганический психоз неуточненный', 'F29', 2594, 'F20-F29', 0, 'Психоз БДУ Исключены: психическое расстройство БДУ (F99) органический или симптоматический психоз БДУ (F09)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2626, 'РАССТРОЙСТВА НАСТРОЕНИЯ [АФФЕКТИВНЫЕ РАССТРОЙСТВА]', 'F30-F39', 2428, 'F00-F99', 7, 'Этот блок включает в себя расстройства, при которых основным наруше-\nнием является изменение эмоций и настроения в сторону депрессии (с\nтревогой или без нее) или в сторону приподнятости. Изменения настро-\nения обычно сопровождаются изменениями общего уровня активности.\nБольшинство других симптомов являются вторичными или легко объясня-\nются на фоне изменений настроения и активности. Такие расстройства\nчаще всего имеют тенденцию к рецидивированию, причем начало отдель-\nного эпизода нередко может связываться со стрессовыми событиями и\nситуациями.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2627, 'Маниакальный эпизод', 'F30', 2626, 'F30-F39', 5, 'Все подрубрики этой трехзначной рубрики должны использоваться только для единственного эпизода. Гипоманиакальный или маниакальный эпизоды в случаях, когда в прошлом уже имели место один или несколько аффективных эпизодов (депрессивный, гипоманиакальный, маниакальный или смешанного характера), должны кодироваться как биполярное аффективное расстройство (F31.-) Включено: биполярное расстройство, одиночный маниакальный эпизод');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2628, 'Гипомания', 'F30.0', 2627, 'F30', 0, 'Расстройство, характеризующееся устойчивым подъемом настроения, повышенной энергичностью и активностью и обычно выраженным ощущением благополучия, умственной и физической продуктивности. Часто имеют место повышенная коммуникабельность, болтливость, излишняя фамильярность, повышенная сексуальность и сниженная потребность во сне, однако не до такой степени, чтобы привести к тяжелым нарушениям деятельности и социальному отторжению. Раздражительность, самомнение, грубость могут замещать более обычные эйфорические взаимоотношения. Нарушения настроения и поведения не сопровождаются галлюцинациями или бредом.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2629, 'Мания без психотических симптомов', 'F30.1', 2627, 'F30', 0, 'Настроение приподнято без связи с реальными обстоятельствами жизни больного и может варьироваться от беззаботной веселости до почти неконтролируемого возбуждения. Приподнятое настроение сопровождается возрастание энергичности, перерастающей в сверхактивность и говорливость, и снижением потребности во сне. Выражена невозможность концентрировать внимание, часто имеет место значительная рассеянность. Чувство самооценки нередко принимает напыщенный характер с грандиозными идеями и сверхсамоуверенностью. Утрата нормальной социальной сдержанности влечет за собой поведение, характеризующееся безрассудностью, рискованностью, неуместностью и несоответствием характеру больного.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2630, 'Мания с психотическими симптомами', 'F30.2', 2627, 'F30', 0, 'В дополнение к клинической картине, описанной в подрубрике F30.1, налицо бред (обычно грандиозный) или галлюцинации (обычно голоса, обращающиеся непосредственно к больному) или возбуждение, чрезмерная двигательная активность, причем вспышки идей столь выражены, что индивид становится недоступным для обычного общения. Мания с: . соответствующими настроению психотическими симптомами . не соответствующими настроению психотическими симптомами Маниакальный ступор');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2631, 'Другие маниакальные эпизоды', 'F30.8', 2627, 'F30', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2632, 'Маниакальный эпизод неуточненный', 'F30.9', 2627, 'F30', 0, 'Мания БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2633, 'Биполярное аффективное расстройство', 'F31', 2626, 'F30-F39', 10, 'Расстройство, характеризующееся двумя или более эпизодами, при которых настроение и уровень активности пациента значительно нарушены. Эти нарушения представляют собой случаи подъема настроения, прилива энергии и усиления активности (гипомания или мания) и случаи падения настроения и резкого снижения энергичности и активности (депрессия). Повторные эпизоды только гипомании или мании классифицируются как биполярные (F31.8). Включены: маниакально-депрессивное(ый)(ая): . заболевание . психоз . реакция Исключены: биполярное расстройство, единственный маниакальный эпизод (F30.-) циклотимия (F34.0)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2634, 'Биполярное аффективное расстройство, текущий эпизод гипомании', 'F31.0', 2633, 'F31', 0, 'У пациента в данный момент имеются гипоманиакальные явления, и в прошлом отмечался, по крайней мере однократно, другой аффективный эпизод (гипоманиакальный, маниакальный, депрессивный или смешенного характера).');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2635, 'Биполярное аффективное расстройство, текущий эпизод мании без психотических симптомов', 'F31.1', 2633, 'F31', 0, 'У пациента в данный момент имеются маниакальные явления без психотической симптоматики (как в подрубрике F30.1), и в прошлом отмечался, по крайней мере однократно, другой аффективный эпизод (гипоманиакальный, маниакальный, депрессивный или смешанного характера).');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2636, 'Биполярное аффективное расстройство, текущий эпизод мании с психотическими симптомами', 'F31.2', 2633, 'F31', 0, 'У пациента в данный момент имеются маниакальные явления с психотической симптоматикой (как в подрубрике F30.2), и в прошлом отмечался, по крайней мере однократно, другой аффективный эпизод (гипоманиакальный, маниакальный, депрессивный или смешанного характера).');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2637, 'Биполярное аффективное расстройство, текущий эпизод легкой или умеренной депрессии', 'F31.3', 2633, 'F31', 0, 'У пациента в данный момент имеются явления депрессии, как при депрессивном эпизоде легкой или средней тяжести (F32.0 или F32.1), и в прошлом отмечался, по крайней мере однократно, подтвержденный гипоманиакальный, маниакальный или смешанный аффективный эпизод.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2638, 'Биполярное аффективное расстройство, текущий эпизод тяжелой депрессии без психотических симптомов', 'F31.4', 2633, 'F31', 0, 'лой депрессии без психотических симптомов У пациента в данный момент имеются явления депрессии, как при тяжелом депрессивном эпизоде без психотической симптоматике (F32.2), и в прошлом отмечался, по крайней мере однократно, подтвержденный гипоманиакальный, маниакальный или смешанный аффективный эпизод.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2639, 'Биполярное аффективное расстройство, текущий эпизод тяжелой депрессии с психотическими симптомами', 'F31.5', 2633, 'F31', 0, 'У пациента в данный момент имеются явления депрессии, как при тяжелом депрессивном эпизоде с психотической симптоматикой (F32.3), и в прошлом отмечался, по крайней мере однократно, подтвержденный гипоманиакальный, маниакальный или смешанный аффективный эпизод.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2640, 'Биполярное аффективное расстройство, текущий эпизод смешанного характера', 'F31.6', 2633, 'F31', 0, 'Пациент в прошлом имел, по крайней мере однократно, подтвержденный гипоманиакальный, маниакальный, депрессивный или смешанный аффективный эпизод, а текущее состояние представляет собой сочетание маниакальных и депрессивных симптомов или их быструю смену. Исключен: одиночный аффективный эпизод смешанного характера (F38.0)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2641, 'Биполярное аффективное расстройство, текущая ремиссия', 'F31.7', 2633, 'F31', 0, 'Пациент в прошлом имел, по крайней мере однократно, подтвержденный гипоманиакальный, маниакальный или смешанный аффективный эпизод и хотя бы один другой аффективный эпизод (гипоманиакальный, маниакальный, депрессивный или смешанный), но в текущий момент он не страдает какими-либо значительными нарушениями настроения, которые отсутствуют уже в течение нескольких месяцев. Периоды ремиссии в течение профилактического лечения должны кодироваться этой же рубрикой.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2642, 'Другие биполярные аффективные расстройства', 'F31.8', 2633, 'F31', 0, 'Биполярное II расстройство Рецидивирующие маниакальные эпизоды');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2643, 'Биполярное аффективное расстройство неуточненное', 'F31.9', 2633, 'F31', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2644, 'Депрессивный эпизод', 'F32', 2626, 'F30-F39', 6, 'В легких, средних или тяжелых типичных случаях депрессивных эпизодов у больного отмечаются пониженное настроение, уменьшение энергичности и падение активности. Снижена способность радоваться, получать удовольствие, интересоваться, сосредоточиваться. Обычным является выраженная усталость даже после минимальных усилий. Обычно нарушен сон и снижен аппетит. Самооценка и уверенность в себе почти всегда снижены, даже при легких формах заболевания. Часто присутствуют мысли о собственной виновности и бесполезности. Пониженное настроение, мало меняющееся день ото дня, не зависит от обстоятельств и может сопровождаться так называемыми соматическими симптомами, такими, как потеря интереса к окружающему и утрата ощущений, доставляющих удовольствие, пробуждение по утрам на несколько часов раньше обычного времени, усиление депрессии по утрам, выраженная психомоторная заторможенность, тревожность, потеря аппетита, похудание и снижение либидо. В зависимости от числа и тяжести симптомов депрессивный эпизод может классифицироваться как легкий, умеренно выраженный и тяжелый. Включены: одиночный эпизод: . депрессивной реакции . психогенной депрессии . реактивной депрессии Исключены: расстройство приспособительных реакций (F43.2) рекуррентное депрессивное расстройство (F33.-) депрессивный эпизод, связанный с расстройствами поведения, классифицированными в рубриках F91.-(F92.0)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2645, 'Депрессивный эпизод легкой степени', 'F32.0', 2644, 'F32', 0, 'Обычно выражены два-три вышеупомянутых симптома. Пациент, конечно, страдает от этого, но, вероятно, будет в состоянии продолжать выполнять основные виды деятельности.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2646, 'Депрессивный эпизод средней степени', 'F32.1', 2644, 'F32', 0, 'Выражены четыре и более из вышеупомянутых симптомов. Пациент, вероятно, испытывает большие трудности при продолжении обычной деятельности.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2647, 'Депрессивный эпизод тяжелой степени без психотических симптомов', 'F32.2', 2644, 'F32', 0, 'Эпизод депрессии, при котором явно выражен ряд вышеупомянутых симптомов, приносящих страдание; обычны снижение самооценки и мысли о собственной никчемности или виновности. Характерны суицидальные мысли и попытки, обычно имеет место ряд псевдосоматических симптомов. Депрессия с возбуждением } Значительная депрессия } одиночный эпизод без Витальная депрессия } психотических симптомов');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2648, 'Депрессивный эпизод тяжелой степени с психотическими симптомами', 'F32.3', 2644, 'F32', 0, 'Эпизод депрессии, как описано в подрубрике F32.3, но с наличием галлюцинаций, бреда, психомоторной заторможенности или ступора, настолько выраженных, что обычная социальная активность невозможна. Имеется опасность для жизни вследствие суицидальных попыток, обезвоживания или голодания. Галлюцинации и бред могут соответствовать или не соответствовать настроению. Одиночный эпизод: . значительной депрессии с психотическими симптомами . психогенного депрессивного психоза . психотической депрессии');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2649, 'Другие депрессивные эпизоды', 'F32.8', 2644, 'F32', 0, 'Атипичная депрессия Одиночный эпизод "скрытой" депрессии БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2650, 'Депрессивный эпизод неуточненный', 'F32.9', 2644, 'F32', 0, 'Депрессия БДУ Депрессивное расстройство БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2651, 'Рекуррентное депрессивное расстройство', 'F33', 2626, 'F30-F39', 7, 'Расстройство, характеризующееся повторными эпизодами депрессии, соответствующими описанию депрессивного эпизода (F32.-), без наличия в анамнезе самостоятельных эпизодов подъема настроения и прилива энергии (мании). Однако могут быть краткие эпизоды легкого подъема настроения и гиперактивности (гипомания) сразу же после депрессивного эпизода, иногда вызванные лечением антидепрессантами. Наиболее тяжелые формы рекуррентного депрессивного расстройства (F33.2 и F33.3) имеют много общего с прежними понятиями, такими, как маниакально-депрессивная депрессия, меланхолия, витальная депрессия и эндогенная депрессия. Первый эпизод может возникнуть в любом возрасте, начиная с детства и до старости. Начало его может быть острым или незаметным, а продолжительность - от нескольких недель до многих месяцев. Никогда полностью не исчезает опасность того, что у больного рекуррентным депрессивным расстройством не возникнет маниакального эпизода. Если такое произойдет, диагноз должен быть изменен на биполярное аффективное расстройство (F31.-). Включены: повторные эпизоды: . депрессивной реакции . психогенной депрессии . реактивной депрессии сезонное депрессивное расстройство Исключены: рекуррентные краткие депрессивные эпизоды (F38.1)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2652, 'Рекуррентное депрессивное расстройство, текущий эпизод легкой степени', 'F33.0', 2651, 'F33', 0, 'Расстройство, характеризующееся повторными эпизодами депрессии. Текущий эпизод легко выражен (как описано в подрубрике F32.0) и без мании в анамнезе.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2653, 'Рекуррентное депрессивное расстройство, текущий эпизод средней степени', 'F33.1', 2651, 'F33', 0, 'Расстройство, характеризующееся повторными эпизодами депрессии. Текущий эпизод умеренно выражен (как описано в подрубрике F32.1) и без мании в анамнезе.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2654, 'Рекуррентное депрессивное расстройство, текущий эпизод тяжелой степени без психотических симптомов', 'F33.2', 2651, 'F33', 0, 'Расстройство, характеризующееся повторными эпизодами депрессии. Текущий эпизод значительно выражен, без психотических симптомов (как описано в подрубрике F32.2) и без мании в анамнезе. Эндогенная депрессия без психотических симптомов Значительная депрессия, рекуррентная без психотических симптомов Маниакально-депрессивный психоз, депрессивный тип без психотических симптомов Витальная депрессия, рекуррентная без психотических симптомов');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2655, 'Рекуррентное депрессивное расстройство, текущий эпизод тяжелой степени с психотическими симптомами', 'F33.3', 2651, 'F33', 0, 'Расстройство, характеризующееся повторными эпизодами депрессии. Текущий эпизод значительно выражен, сопровождается психотической симптоматикой, как описано в подрубрике F32.3, но без указаний на предыдущие эпизоды мании. Эндогенная депрессия с психотическими симптомами Маниакально-депрессивный психоз, депрессивный тип с психотическими симптомами Повторные тяжелые эпизоды: . значительной депрессии с психотическими симптомами . психогенного депрессивного психоза . психотичсекой депрессии . реактивного депрессивного психоза');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2656, 'Рекуррентное депрессивное расстройство, текущее состояние ремиссии', 'F33.4', 2651, 'F33', 0, 'У пациента в прошлом отмечались два или более депрессивных эпизода (как описано в подрубриках F33.0-F33.3), но уже в течение нескольких месяцев депрессивная симптоматика отсутствует.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2657, 'Другие рекуррентные депрессивные расстройства', 'F33.8', 2651, 'F33', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2658, 'Рекуррентное депрессивное расстройство неуточненное', 'F33.9', 2651, 'F33', 0, 'Монополярная депрессия БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2659, 'Устойчивые расстройства настроения [аффективные расстройства]', 'F34', 2626, 'F30-F39', 4, 'Стойкие и обычно колеблющиеся расстройства настроения, при которых большинство отдельных эпизодов недостаточно тяжелы, чтобы позволить описать их как гипоманиакальный или легкий депрессивный эпизод. Поскольку он длятся многие годы, а иногда значительную часть жизни больного, они вызывают выраженное недомогание и нетрудоспособность. В отдельных случаях повторные или единичный маниакальный или депрессивный эпизоды могут накладываться на хроническое аффективное расстройство.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2660, 'Циклотимия', 'F34.0', 2659, 'F34', 0, 'Устойчивая нестабильность настроения, включающая ряд периодов депрессии и легкой приподнятости настроения, ни один из которых не является достаточно тяжелым или длительным, чтобы поставить диагноз биполярного аффективного расстройства (F31.-) или рекуррентного депрессивного расстройства (F33.-). Такое расстройство часто обнаруживается у родственников больного, страдающего биполярным аффективным расстройством. У некоторых пациентов с циклотимией в конце концов развивается биполярное аффективное расстройство. Аффективное расстройство личности Циклоидная личность Циклотимическая личность');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2661, 'Дистимия', 'F34.1', 2659, 'F34', 0, 'Хроническое депрессивное настроение, продолжающееся по меньшей мере несколько лет, которое является недостаточно тяжелым или при котором отдельные эпизоды недостаточно длительны, чтобы можно было поставить диагноз рекуррентного депрессивного расстройства тяжелой, средней или легкой степени выраженности (F33.-). Депрессивный(ое): . невроз . расстройство личности Невротическая депрессия Устойчивая тревожная депрессия Исключено: тревожная депрессия (легкая или неустойчивая) (F41.2)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2662, 'Другие устойчивые расстройства настроения [аффективные]', 'F34.8', 2659, 'F34', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2663, 'Устойчивое расстройство настроения [аффективное] неуточненное', 'F34.9', 2659, 'F34', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2664, 'Другие расстройства настроения [аффективные]', 'F38', 2626, 'F30-F39', 3, 'Любые другие расстройства настроения, не дающие оснований классифицировать их рубриками F30-F34, поскольку они недостаточно тяжелы или продолжительны.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2665, 'Другие одиночные расстройства настроения [аффективные]', 'F38.0', 2664, 'F38', 0, 'Смешанный аффективный эпизод');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2666, 'Другие рекуррентные расстройства настроения [аффективные]', 'F38.1', 2664, 'F38', 0, 'Повторные краткие депрессивные эпизоды');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2667, 'Другие уточненные расстройства настроения [аффективные]', 'F38.8', 2664, 'F38', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2668, 'Расстройство настроения [аффективное] неуточненное', 'F39', 2626, 'F30-F39', 0, 'Аффективный психоз БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2669, 'НЕВРОТИЧЕСКИЕ, СВЯЗАННЫЕ СО СТРЕССОМ И СОМАТОФОРМНЫЕ РАССТРОЙСТВА', 'F40-F48', 2428, 'F00-F99', 7, 'Исключены: связанные с расстройствами поведения, классифицированными в рубриках F91.-(F92.8)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2670, 'Фобические тревожные расстройства', 'F40', 2669, 'F40-F48', 5, 'Группа расстройств, при которых единственным или преобладающим симптомом является боязнь определенных ситуаций, не представляющих текущей опасности. В результате больной обычно избегает или страшится таких ситуаций. Беспокойство больного может быть сфокусировано на отдельных симптомах, таких, как дрожь от страха или обморочное ощущение, и часто ассоциируется с боязнью умереть, потерять над собой контроль или сойти с ума. Ожидание возможности попадания в фобическую ситуацию обычно вызывает преждевременную тревогу. Фобическая тревожность и депрессия часто сочетаются. Решение о постановке двух диагнозов (фобическое тревожное расстройство и депрессивный эпизод) или только одного определяется продолжительностью этих состояний и соображениями врача в отношении терапии во время консультации больного.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2671, 'Агорафобия', 'F40.0', 2670, 'F40', 0, 'Довольно хорошо очерченная группа фобий, включающая в себя боязнь выходить из дома, входить в магазины, боязнь толпы и общественных мест, боязнь в одиночку путешествовать поездом, автобусом, самолетом. Паническое расстройство является обычной чертой эпизодов и в прошлом, и в настоящем. Кроме того, в качестве дополнительной характеристики часто присутствуют депрессивный и навязчивые симптомы и социальные фобии. Часто выражено избегание фобических ситуаций, и лица, страдающие агорафобией, не испытывают большого беспокойства, так как они в состоянии избежать этих "опасностей". Агорафобия без панического расстройства в анамнезе Паническое расстройство с агорафобией');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2672, 'Социальные фобии', 'F40.1', 2670, 'F40', 0, 'Боязнь пристального внимания со стороны других людей, ведущая к избеганию социальных ситуаций. Более глубокие социальные фобии связаны с низкой самооценкой и боязнью критики. Их присутствие проявляется в виде покраснения лица, дрожания рук, тошноты, постоянных позывов на мочеиспускание. Иногда больной убежден, что какое-либо из этих вторичных проявлений и составляет его основную проблему. Симптоматика может прогрессировать до приступов паники. Антропофобия Социальный невроз');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2673, 'Специфические (изолированные) фобии', 'F40.2', 2670, 'F40', 0, 'Сюда входят фобии, ограниченные весьма специфичными ситуациями, такими, как близость особых животных, высота, гром, темнота, полет, закрытое пространство, мочеиспускание и дефекация в общественных туалетах, употребление определенных пищевых продуктов, лечение зубов, вид крови или травмы. Хотя мысль о такой ситуации является абстрактной, попадание в нее может вызвать панику, как при агорафобии или социальной фобии. Акрофобия Боязнь животных Клаустрофобия Простая фобия Исключены: дисморфофобия (небредовая) (F45.2) боязнь заболеть (нозофобия) (F45.2)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2674, 'Другие фобические тревожные расстройства', 'F40.8', 2670, 'F40', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2675, 'Фобическое тревожное расстройство неуточненное', 'F40.9', 2670, 'F40', 0, 'Фобия БДУ Фобическое состояние БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2676, 'Другие тревожные расстройства', 'F41', 2669, 'F40-F48', 6, 'Расстройства, при которых проявление тревоги является основным симптомом и не ограничивается какой-либо конкретной внешней ситуацией. Могут также присутствовать депрессивные и навязчивые симптомы и даже некоторые элементы фобической тревожности при условии, что они несомненно являются вторичными и менее тяжелыми.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2677, 'Паническое расстройство [эпизодическая пароксизмальная тревожность]', 'F41.0', 2676, 'F41', 0, 'Характерной чертой расстройства являются рецидивируюие приступы резко выраженной тревоги (паники), которые не ограничены какой-либо особой ситуацией или комплексом обстоятельств и, следовательно, непредсказуемы. Как и при других тревожных расстройствах, основная симптоматика включает внезапное возникновение сердцебиений, боли за грудиной, ощущение удушья, тошноту и чувство нереальности (деперсонализация или дереализация). Кроме того, как вторичное явление часто присутствует боязнь умереть, потерять контроль над собой или сойти с ума. Паническое расстройство не следует использовать в качестве основного диагноза, если у пациента имелось депрессивное расстройство в начале приступа паники. В этом случае приступ паники, вероятнее всего, является вторичным по отношению к депрессии. Панический(ое): . приступ . состояние Исключено: паническое расстройство с агорафобией (F40.0)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2678, 'Генерализованное тревожное расстройство', 'F41.1', 2676, 'F41', 0, 'Тревога, которая является распространенной и устойчивой, но не ограниченной или преимущественно вызванной какимилибо особыми обстоятельствами (т.е. свободно плавающей, или "free-floating"). Доминирующие симптомы изменчивы, но включают жалобы на устойчивую нервозность, ощущение страха, мышечное напряжение, потливость, ощущение безумства, дрожь, головокружение и чувство дискомфорта в эпигастральной области. Часто выражена боязнь несчастного случая или болезни, которые, по мнению больного ожидают его или его родственников в ближайшее время. Тревожная(ое): . реакция . состояние Невроз тревоги Исключена: неврастения (F48.0)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2679, 'Смешанное тревожное и депрессивное расстройство', 'F41.2', 2676, 'F41', 0, 'Эту рубрику следует использовать в том случае, когда присутствуют одновременно и тревожность, и депрессия, но ни одно из этих состояний не является превалирующим, а степень выраженности их симптоматики не позволяет при рассмотрении каждого поставить отдельный диагноз. Если же симптомы и тревожности, и депрессии настолько выражены, что позволяют поставить отдельный диагноз каждого из этих расстройств, следует кодировать оба диагноза, и в этом случае данная рубрика не должна использоваться. Тревожная депрессия (легкая или неустойчивая)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2680, 'Другие смешанные тревожные расстройства', 'F41.3', 2676, 'F41', 0, 'Симптомы тревожности сочетаются с чертами других расстройств, классифицированных в рубриках F42-F48. При этом степень выраженности симптомов этих расстройств не является столь тяжелой, чтобы можно было поставить диагноз, если их рассматривать раздельно.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2681, 'Другие уточненные тревожные расстройства', 'F41.8', 2676, 'F41', 0, 'Тревожная истерия');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2682, 'Тревожное расстройство неуточненное', 'F41.9', 2676, 'F41', 0, 'Тревожность БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2683, 'Обсессивно-компульсивное расстройство', 'F42', 2669, 'F40-F48', 5, 'Существенной особенностью состояния является наличие повторяющихся навязчивых мыслей или вынужденных действий. Навязчивые мысли представляют собой идеи, образы или побуждения, которые вновь и вновь приходят больному в голову в стереотипном виде. Они почти всегда огорчительны, и пациент часто безуспешно пытается сопротивляться им. Тем не менее больной считает эти мысли своими собственными, даже если они непроизвольны и отвратительны. Навязчивые действия, или ритуалы, являются стереотипными манерами, которые больной повторяет вновь и вновь. Они не являются способом получить удовольствие или атрибутом выполнения полезных задач. Эти действия являются способом предотвратить возможность наступления неприятного события, которое, как опасается больной, в противном случае может произойти, нанеся вред ему или им другому лицу. Обычно такое поведение осознается больным как бессмысленное или неэффективное и делаются повторные попытки противостоять ему. Почти всегда присутствует тревожность. Если компульсивные действия подавляются, тревожность становится более выраженной. Включены: ананкастический невроз обсессивно-компульсивный невроз Исключена: обсессивно-компульсивная личность (расстройство) (F60.5)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2684, 'Преимущественно навязчивые мысли или размышления', 'F42.0', 2683, 'F42', 0, 'Они могут принимать форму идей, мысленных образов или побуждений к действию, которые почти всегда причиняют страдание пациенту. Иногда идеи являются незаконченными, бесконечно рассматриваемыми альтернативами, связанными с неспособностью принять обычное, но необходимое решение, касающееся повседневной жизни. Связь между навязчивыми размышлениями и депрессией является особенно тесной, поэтому диагнозу обсессивно-компульсивного расстройства следует отдать предпочтение лишь только в том случае, если навязчивые мысли возникают или удерживаются при отсутствии депрессивного эпизода.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2685, 'Преимущественно компульсивное действие [навязчивые ритуалы]', 'F42.1', 2683, 'F42', 0, 'Большинство компульсивных действий относится к очистке от загрязнения (в основном мытье рук), повторным проверкам для получения гарантии того, что потенциально опасная ситуация не может возникнуть, или соблюдению аккуратности и опрятности. В основе такого явного поведения лежит обычно боязнь опасности, которой может подвергнуться сам пациент или которой он может подвергнуть другого, и ритуальные действия являются безрезультатной или символической попыткой предотвратить опасность.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2686, 'Смешанные навязчивые мысли и действия', 'F42.2', 2683, 'F42', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2687, 'Другие обсессивно-компульсивные расстройства', 'F42.8', 2683, 'F42', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2688, 'Обсессивно-компульсивное расстройство неуточненное', 'F42.9', 2683, 'F42', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2689, 'Реакция на тяжелый стресс и нарушения адаптации', 'F43', 2669, 'F40-F48', 5, 'Эта группа расстройств отличается от других групп тем, что в нее включены расстройства, идентифицируемые не только на основе симптоматики и характера течения, но также на основе очевидности влияния одной или даже обеих причин: исключительно неблагоприятного события в жизни, вызвавшего острую стрессовую реакцию, или значительной перемены в жизни, ведущей к продолжительным неприятным обстоятельствам и обусловившей нарушения адаптации. Хотя менее тяжелый психосоциальный стресс (жизненные обстоятельства) может ускорить начало или способствовать проявлению широкого спектра расстройств, представленных в этом классе заболеваний, его этиологическая значимость не всегда ясна, и в каждом случае будет признаваться зависимость от индивида, часто от его сверхчувствительности и уязвимости (т.е. жизненные события не являются обязательными или достаточными, чтобы объяснить возникновение и форму расстройства). Расстройства, собранные в этой рубрике, напротив, всегда рассматриваются как непосредственное следствие острого тяжелого стресса или продолжительного травмирования. Стрессовые события или продолжительные неприятные обстоятельства являются первичным или преобладающим причинным фактором и расстройство не могло бы возникнуть без их влияния. Таким образом, расстройства, классифицированные в этой рубрике, могут рассматриваться как извращенные приспособительные реакции на тяжелый или продолжительный стресс, при этом они мешают успешно справиться со стрессом и, следовательно, ведут к проблемам социального функционирования.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2690, 'Острая реакция на стресс', 'F43.0', 2689, 'F43', 0, 'Преходящее расстройство, которое развивается у человека без каких-либо других проявлений психических расстройств в ответ на необычный физический или психический стресс и обычно стихает через несколько часов или дней. В распространенности и тяжести стрессовых реакций имеют значение индивидуальная ранимость и способность владеть собой. Симптомы показывают типичную смешанную и изменчивую картину и включают первоначальное состояние "ошеломления" с некоторым сужением области сознания и внимания, невозможностью полностью осознать раздражители и дезориентированностью. Это состояние может сопровождаться последующим "уходом" из окружающей ситуации (до состояния диссоциативного ступора - F44.2) или ажиатацией и сверхактивностью (реакция полета или фуги). Обычно присутствуют отдельные черты панического расстройства (тахикардия, избыточное потоотделение, покраснение). Симптоматика обычно проявляется через несколько минут после воздействия стрессовых стимулов или события и исчезает через 2-3 дня (часто через несколько часов). Может присутствовать частичная или полная амнезия (F44.0) на стрессовое событие. Если вышеуказанная симптоматика устойчива, необходимо изменить диагноз. Острая: . кризисная реакция . реакция на стресс Нервная демобилизация Кризисное состояние Психический шок');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2691, 'Посттравматическое стрессовое расстройство', 'F43.1', 2689, 'F43', 0, 'Возникает как отсроченный или затянувшийся ответ на стрессовое событие (краткое или продолжительное) исключительно угрожающего или катастрофического характера, которое может вызвать глубокий стресс почти у каждого. Предрасполагающие факторы, такие, как личностные особенности (компульсивность, астеничность) или нервное заболевание в анамнезе, могут снизить порог для развития синдрома или усугубить его течение, но они никогда не являются необходимыми или достаточными для объяснения его возникновения. Типичные признаки включают эпизоды повторяющихся переживаний травмирующего события в навязчивых воспоминаниях ("кадрах"), мыслях или кошмарах, появляющихся на устойчивом фоне чувства оцепенения, эмоциональной заторможенности, отчужденности от других людей, безответности на окружающее и избегания действий и ситуаций, напоминающих о травме. Обычно имеют место перевозбуждение и выраженная сверхнастороженность, повышенная реакция на испуг и бессонница. С вышеупомянутыми симптомами часто связаны тревожность и депрессия, и не редкостью являются идеи самоубийства. Появлению симптомов расстройства предшествует латентный период после травмы, колеблющийся от нескольких недель до нескольких месяцев. Течение расстройства различно, но в большинстве случаев можно ожидать выздоровления. В некоторых случаях состояние может принять хроническое течение на многие годы с возможным переходом в устойчивое изменение личности (F62.0). Травматический невроз');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2692, 'Расстройство приспособительных реакций', 'F43.2', 2689, 'F43', 0, 'Состояние субъективного дистресса и эмоционального расстройства, создающее трудности для общественной деятельности и поступков, возникающее в период адаптации к значительному изменению в жизни или стрессовому событию. Стрессовое событие может нарушить целостность социальных связей индивида (тяжелая утрата, разлука) или широкую систему социальной поддержки и ценностей (миграция, статус беженца) либо представлять широкий диапазон изменений и переломов в жизни (поступление в школу, приобретение статуса родителей, неудача в достижении заветной личной цели, уход в отставку). Индивидуальная предрасположенность или ранимость играют важную роль в риске возникновения и форме проявления расстройств приспособительных реакций, однако не допускается возможность возникновения таких расстройств без травмирующего фактора. Проявления очень вариабельны и включают подавленность настроения, настороженность или беспокойство (или комплекс этих состояний), ощущение неспособности справиться с ситуацией, запланировать все заранее или решить оставаться в настоящей ситуации, а также включает некоторую степень снижения способности действовать в повседневной жизни. Одновременно могут присоединяться расстройства поведения, особенно в юношеском возрасте. Характерной чертой может быть краткая или длительная депрессивная реакция или нарушение других эмоций и поведения. Культурный шок Реакция горя Госпитализм у детей Исключено: тревожное расстройство у детей, вызванное разлукой (F93.0)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2693, 'Другие реакции на тяжелый стресс', 'F43.8', 2689, 'F43', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2694, 'Реакция на тяжелый стресс неуточненная', 'F43.9', 2689, 'F43', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2695, 'Диссоциативные [конверсионные] расстройства', 'F44', 2669, 'F40-F48', 10, 'Общепринятыми положениями, на основе которых выделяются диссоциативные, или конверсионные, расстройства, являются полная или частичная потеря нормальной интеграции между памятью на прошлые события, способностью осознать себя как личность и непосредственными ощущениями и способностью управлять движениями тела. Все виды диссоциативных расстройств имеют тенденцию к исчезновению через несколько недель или месяцев, особенно если их возникновение связано с каким-либо травмирующем событием в жизни. Многие хронические расстройства, особенно параличи и потеря чувствительности, могут развиваться на основе существования неразрешимых проблем и межличностных сложностей. Эти расстройства ранее преимущественно классифицировались как различные виды "конверсионной истерии". Считается, что они имеют психогенную этиологию, поскольку по времени возникновения тесно связаны с травмирующими событиями, неразрешимыми и невыносимыми проблемами или нарушенными взаимоотношениями. Симптомы часто соответствуют представлению больного о том, как должно было бы проявляться психическое заболевание. Медицинский осмотр и обследование не выявляют каких-либо явных физических или неврологических нарушений. Кроме того, совершенно очевидно, что потеря функции является выражением эмоционального конфликта или потребностей. Симптомы могут развиваться в тесной связи с психологическим стрессом и часто проявляются внезапно. В эту рубрику включены только расстройства физических функций, в норме произвольно контролирующихся, и потеря чувствительности. Расстройства, включающие болевые ощущения и комплекс других физических ощущений, опосредованных через вегетативную нервную систему, классифицированы в рубрике психосоматических нарушений (F45.0). Всегда следует помнить о возможности развития в дальнейшем серьезных физических или психических расстройств. Включены: конверсионная: . истерия . реакция истерия истерический психоз Исключена: симуляция [сознательная симуляция] (Z76.5)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2696, 'Диссоциативная амнезия', 'F44.0', 2695, 'F44', 0, 'Основной чертой является потеря памяти, особенно на важные недавние события, которая не вызвана органическим психическим заболевание и слишком выражена, чтобы ее можно было объяснить обычной забывчивостью или усталостью. Амнезия обычно сконцентрирована на травмирующих событиях, таких, как несчастный случай или неожиданная тяжелая утрата, и обычно является частичной и избирательной. Полная и генерализованная амнезия редка и обычно является частью амбулаторного автоматизма (фуги) (F44.1); в этом случае расстройство так и следует классифицировать. Диагноз диссоциативной амнезии не следует ставить при наличии органического заболевания мозга, интоксикации или чрезмерной усталости. Исключены: амнестическое расстройство, вызванное употреблением алкоголя или другого психоактивного вещества (F10-F19 c общим четвертым знаком .6) амнезия: . БДУ (R41.3) . антероградная (R41.1) . ретроградная (R41.2) неалкогольный органический амнестический синдром (F04) амнезия после приступа эпилепсии (G40.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2697, 'Диссоциативная фуга', 'F44.1', 2695, 'F44', 0, 'Диссоциативная фуга имеет все черты диссоциативной амнезии в сочетании с целенаправленными передвижениями, выходящими за обычный каждодневный предел. Хотя в период фуги имеет место амнезия, посторонним наблюдателям поведение пациента в это время может казаться абсолютно нормальным. Исключено: фуга после приступа эпилепсии (G40.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2698, 'Диссоциативный ступор', 'F44.2', 2695, 'F44', 0, 'Диссоциативный ступор диагностируется на основании выраженного уменьшения или отсутствия произвольных движений и нормальных ответных реакций на внешние раздражители, такие, как свет, шум, прикосновение, однако осмотр и обследование не обнаруживают явной физической причины. Кроме того, имеет место абсолютная очевидность психогенной причины в виде недавних стрессовых событий или проблем. Исключены: органическое кататоническое расстройство (F06.1) ступор: . БДУ (R40.1) . кататонический (F20.2) . депрессивный (F31-F33) . маниакальный (F30.2)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2699, 'Транс и одержимость', 'F44.3', 2695, 'F44', 0, 'Расстройства, при которых имеет место временная потеря ощущения себя как личности и полная неосознанность окружающего. В эту рубрику включены только состояния транса, которые непроизвольны и нежелательны и возникают вне религиозных или культурно-приемлемых ситуаций. Исключены: состояния, связанные с: . острыми или преходящими психотическими расстройствами (F23.-) . расстройством личности органической этиологии (F07.0) . постконтузионным синдромом (F07.2) . интоксикацией, вызванной употреблением психоактивных веществ (F10-F19 с общим четвертым знаком .0) . шизофренией (F20.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2700, 'Диссоциативные двигательные расстройства', 'F44.4', 2695, 'F44', 0, 'При всем разнообразии имеет место полная или частичная потеря способности двигать конечностью или конечностями. Может отмечаться тесное сходство почти с любым видом атаксии, апраксии, акинезии, афонии, дизартрии, дискинезии, припадка или паралича. Психогенная: . афония . дисфония');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2701, 'Диссоциативные конвульсии', 'F44.5', 2695, 'F44', 0, 'Диссоциативные конвульсии могут имитировать эпилептический припадок, однако прикусывание языка, кровоподтеки, связанные с падением, и непроизвольное мочеиспускание редки. Сознание сохранено либо заменено состоянием ступора или транса.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2702, 'Диссоциативная анестезия или потеря чувственного восприятия', 'F44.6', 2695, 'F44', 0, 'Области кожной анестезии часто имеют границы. Это означает, что они связаны с представлениями пациента о функциях тела, отличающимися от медицинских знаний. Может иметь место потеря различий между сенсорными модуляциями, которая необязательно обусловлена неврологическими повреждениями. Потеря чувственного восприятия может сопровождаться жалобами на парестезию. Потеря зрения и слуха при диссоциативных расстройствах редко бывает тотальной. Психогенная глухота');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2703, 'Смешанные диссоциативные [конверсионные] расстройства', 'F44.7', 2695, 'F44', 0, 'Сочетание расстройств, классифицированных в рубриках F44.0-F44.6');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2704, 'Другие диссоциативные [конверсионные] расстройства', 'F44.8', 2695, 'F44', 0, 'Синдром Ганзера Сложная личность Психогенное: . замешательство . сумеречное состояние');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2705, 'Диссоциативное [конверсионное] расстройство неуточненное', 'F44.9', 2695, 'F44', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2706, 'Соматоформные расстройства', 'F45', 2669, 'F40-F48', 7, 'Главной особенностью является повторное предъявление соматической симптоматики одновременно с настойчивыми требованиями медицинских обследований, несмотря на повторные отрицательные их результаты и заверения врачей, что симптомы не имеют соматической природы. Если у больного имеются какие-либо соматические заболевания, они не объясняют природы и степени выраженности симптомов или страдания или жалоб пациента. Исключены: диссоциативные расстройства (F44.-) выдергивание волос (F98.4) детская форма речи [лепет] (F80.0) сюсюканье (F80.8) кусание ногтей (F98.8) психологические и поведенческие факторы, связанные с нарушениями или болезнями, классифицированными в других рубриках (F54) сексуальная дисфункция, не обусловленная органическими нарушениями или болезнями (F52.-) сосание пальца (F98.8) тики (в детстве и подростковом возрасте) (F95.-) синдром де ла Туретта (F95.2) трихотилломания (F63.3)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2707, 'Соматизированное расстройство', 'F45.0', 2706, 'F45', 0, 'Основными чертами являются многочисленные, повторные, часто меняющиеся физические симптомы, имеющие место по крайней мере в течение двух лет. Большинство пациентов имеют длительную и сложную историю контактов со службами первичной и специализированной медицинской помощи, в ходе которых могло быть выполнено множество безрезультатных исследований и бесплодных диагностических манипуляций. Симптоматика может относиться к любой части тела или системе органов. Течение расстройства хроническое и неустойчивое и часто ассоциируется с нарушением социального, межличностного и семейного поведения. Непродолжительно существующие (менее двух лет) и менее ярко выраженные примеры симптоматики должны классифицироваться как недифференцированное соматоформное расстройство (F45.1). Множественное психосоматическое расстройство Исключена: симуляция [сознательная симуляция] (Z76.5)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2708, 'Недифференцированное соматоформное расстройство', 'F45.1', 2706, 'F45', 0, 'Диагноз недифференцированного соматоформного расстройства следует ставить тогда, когда жалобы пациента многочисленны, вариабельны и устойчивы, но не удовлетворяют полной и типичной клинической картине соматизированного расстройства. Недифференцированное психосоматическое расстройство');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2709, 'Ипохондрическое расстройство', 'F45.2', 2706, 'F45', 0, 'Важнейшей чертой является устойчивая озабоченность пациента возможностью иметь у себя тяжелое, прогрессирующее заболевание или несколько заболеваний. Пациент предъявляет устойчивые соматические жалобы или проявляет устойчивое беспокойство по поводу их возникновения. Нормальные, обычные ощущения и признаки часто воспринимаются больным как ненормальные, беспокоящие; он сосредоточивает свое внимание обычно только на одном-двух органах или системах организма. Часто присутствуют выраженная депрессия и тревога, что может объяснить дополнительные диагнозы. Расстройство, выражающееся в озабоченности собственным здоровьем Дисморфофобия (небредовая) Ипохондрический невроз Ипохондрия Нозофобия Исключены: бредовая дисморфофобия (F22.8) бред, фиксированный на функционировании или внешнем виде собственного тела (F22.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2710, 'Соматоформная дисфункция вегетативной нервной системы', 'F45.3', 2706, 'F45', 0, 'Симптоматика, предъявляемая пациентом подобна той, которая возникает при повреждении органа или системы органов, преимущественно или полностью иннервируемых и контролируемых вегетативной нервной системой, т.е. сердечно-сосудистой, желудочно-кишечной, дыхательной и мочеполовой систем. Симптомы обычно бывают двух типов, ни один из которых не указывает на нарушение конкретного органа или системы. Первый тип симптомов - это жалобы, основанные на объективных признаках вегетативного раздражения, таких, как сердцебиение, потливость, покраснение, тремор и выражение страха и беспокойства относительно возможного нарушения здоровья. Второй тип симптомов - это субъективные жалобы неспецифического или изменчивого характера, такие, как быстротечные боли по всему телу, ощущение жара, тяжести, усталости или вздутия живота, которые пациент соотносит с каким-либо органом или системой органов. Кардинальный невроз Синдром да Косты Гастроневроз Нейроциркуляторная астения Психогенные формы: . аэрофагии . кашля . диареи . диспепсии . дизурии . метеоризма . икоты . глубокого и частого дыхания . учащенного мочеиспускания . синдрома раздраженного кишечника . пилороспазма Исключены: психологические и поведенческие факторы, связанные с нарушениями или болезнями, классифицированными в других рубриках (F54)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2711, 'Устойчивое соматоформное болевое расстройство', 'F45.4', 2706, 'F45', 0, 'Основной жалобой является устойчивая, резкая мучительная боль, которую нельзя полностью объяснить физиологическим нарушением или соматическим заболеванием и которая возникает в связи с эмоциональным конфликтом или психосоциальными проблемами, что позволяет рассматривать их как основную этиологическую причину. Результатом обычно является заметное усиление поддержки и внимания личностного или медицинского характера. Боль психогенной природы, возникающая в процессе депрессивного расстройства или шизофрении, не может быть отнесена к этой рубрике. Психалгия Психогенная: . боль в спине . головная боль Соматоформное болевое расстройство Исключены: боль в спине БДУ (M54.9) боль: . БДУ (R52.9) . острая (R52.0) . хроническая (R52.2) . неустранимая (R52.1) головная боль напряженного типа (G44.2)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2712, 'Другие соматоформные расстройства', 'F45.8', 2706, 'F45', 0, 'Какие-либо другие расстройства чувствительности, функций или поведения, возникающие не вследствие соматических нарушений. Расстройства, которые не опосредованы через вегетативную нервную систему, ограничены определенными системами или участками тела и имеют тесную временную связь с травмирующими событиями или проблемами. Психогенная(ый): . дисменорея . дисфагия, включая "глобус истерикус" (globus hystericus) . зуд . кривошея Скрежетание зубами');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2713, 'Соматоформное расстройство неуточненное', 'F45.9', 2706, 'F45', 0, 'Психосоматическое расстройство БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2714, 'Другие невротические расстройства', 'F48', 2669, 'F40-F48', 4, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2715, 'Неврастения', 'F48.0', 2714, 'F48', 0, 'При этом расстройстве проявляется значительная, связанная с культурой вариабельность. Выделяются два основных типа расстройства, в значительной степени перекрывающих друг друга. Главной характерной чертой первого типа являются жалобы на повышенную утомляемость после умственной нагрузки, с которой часто связано некоторое снижение производственных показателей или продуктивности в повседневных делах. Умственная утомляемость описывается больным как неприятное возникновение рассеянности, ослабления памяти, невозможности сосредоточиться и неэффективности умственной деятельности. При другом типе расстройства основной упор делается на ощущение физической слабости и изнеможения даже после минимальной нагрузки, сопровождаемых ощущением мышечных болей и невозможностью расслабиться. Оба типа расстройства характеризуются рядом общих неприятных физических ощущений, таких, как головокружение, напряженная головная боль и ощущение общей нестабильности. Общими чертами являются также беспокойство по поводу снижения своих умственных и физических способностей, раздражительность, утрата способности радоваться и незначительно выраженная депрессия и тревога. Сон часто нарушен в своей начальной и средней фазе, но может также быть выраженной и сонливость. Синдром утомляемости При необходимости идентифицировать соматическое заболевание, предшествовавшее данному расстройству, используют дополнительный код. Исключены: астения БДУ (R53) состояние истощения жизненных сил (Z73.0) недомогание и утомляемость (R53) синдром утомляемости после перенесенной вирусной болезни (G93.3) психастения (F48.8)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2716, 'Синдром деперсонализации-дереализации', 'F48.1', 2714, 'F48', 0, 'Редкое расстройство, при котором пациент непроизвольно жалуется на то, что его умственная деятельность, тело и окружающее качественно изменены так, что представляются нереальными, удаленными или автоматизированными. Среди различных проявлений этого синдрома самое частое - это потеря эмоций и ощущение холодности или отстраненности от своих мыслей, от своего тела или реального мира. Несмотря на драматический характер переживаний, пациент осознает нереальность этих изменений. Сознание сохраняется, и не утрачивается способность выражать эмоции. Синдром деперсонализации-дереализации может быть составной частью диагностируемой шизофрении, депрессивного, фобического или обессивно-компульсивного расстройства. В этом случае диагноз ставится по основному расстройству.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2717, 'Другие уточненные невротические расстройства', 'F48.8', 2714, 'F48', 0, 'Болезнь Брике Синдром Дата Профессиональный невроз, в том числе писчий спазм Психастения Психастенический невроз Психогенный обморок');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2718, 'Невротическое расстройство неуточненное', 'F48.9', 2714, 'F48', 0, 'Невроз БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2719, 'ПОВЕДЕНЧЕСКИЕ СИНДРОМЫ, СВЯЗАННЫЕ С ФИЗИОЛОГИЧЕСКИМИ НАРУШЕНИЯМИ И ФИЗИЧЕСКИМИ ФАКТОРАМИ (F50-F59)', 'F50-F59', 2428, 'F00-F99', 7, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2720, 'Расстройства приема пищи', 'F50', 2719, 'F50-F59', 8, 'Исключены: анорексия БДУ (R63.0) трудности вскармливания и введения пищи (R63.3) расстройство приема пищи в младенческом и детском возрасте (F98.2) полифагия (R63.2)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2721, 'Нервная анорексия', 'F50.0', 2720, 'F50', 0, 'Расстройство, характеризующееся преднамеренной потерей массы тела, вызванной и поддерживаемой пациентом. Это расстройство, как правило, чаще встречается у девочек подросткового возраста и молодых женщин, но ему могут быть подвержены юноши и молодые мужчины, а также дети, приближающиеся к пубертатному периоду, и женщины старшего возраста (вплоть до наступления менопаузы). Расстройство ассоциируется со специфической психопатологической боязнью ожирения и дряблости фигуры, которая становится назойливой идеей, и пациенты устанавливают для себя низкий предел массы тела. Как правило, имеют место различные вторичные эндокринные и обменные нарушения и функциональные расстройства. Симптоматика включает ограничение диеты, чрезмерную физическую нагрузку, прием рвотных, слабительных и мочегонных средств, а также препаратов, понижающих аппетит. Исключены: потеря аппетита (R63.0) психогенная (F50.8)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2722, 'Атипичная нервная анорексия', 'F50.1', 2720, 'F50', 0, 'Расстройство, отвечающее некоторым чертам нервной анорексии, но полная клиническая картина которого не позволяет поставить этот диагноз. Так, один из ключевых симптомов вышеуказанного расстройства, такой, как аменорея или выраженная боязнь ожирения, может отсутствовать при наличии заметной потери массы тела и поведения, направленного на достижение похудания. Этот диагноз не следует ставить, если имеются свидетельства наличия соматического заболевания, вызывающего потерю массы тела.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2723, 'Нервная булимия', 'F50.2', 2720, 'F50', 0, 'Синдром, характеризующийся повторными приступами переедания и выраженным беспокойством по поводу контроля за массой тела. Это приводит к выработке стиля переедания, сопровождаемого вызовом рвоты и использованием слабительных средств. Это расстройство имеет много общего с нервной анорексией, включая сверхозабоченность свой фигурой и массой тела. Повторные рвоты чреваты нарушениями электролитного баланса и соматическими осложнениями. Часто (но не всегда) в анамнезе пациента отмечается ранее имевший место эпизод нервной анорексии с колебаниями его давности от нескольких месяцев до нескольких лет. Булимия БДУ Нервная кинорексия');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2724, 'Атипичная нервная булимия', 'F50.3', 2720, 'F50', 0, 'Расстройство, имеющее некоторые признаки нервной булимии, но полная клиническая картина не позволяет поставить этот диагноз. Например, могут иметь место повторные приступы переедания и чрезмерное употребление слабительных средств без значительных изменений массы тела или может отсутствовать типичная сверхозабоченность собственной фигурой и массой тела.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2725, 'Переедание, связанное с другими психологическими расстройствами', 'F50.4', 2720, 'F50', 0, 'Переедание вследствие стрессовых событий, таких, как тяжелая утрата, несчастный случай, рождение ребенка и т.д. Психогенное переедание Исключено: ожирение (E66.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2726, 'Рвота, связанная с другими психологическими расстройствами', 'F50.5', 2720, 'F50', 0, 'Повторная рвота, которая возникает при диссоциативных расстройствах (F44.-) и ипохондрическом расстройстве (F45.2) и которая не является исключительно следствием состояний, не входящих в перечень данного класса. Эта подрубрика может также использоваться как дополнение к рубрике O21.- (Чрезмерная рвота при беременности), когда эмоциональные факторы доминируют в причине повторной тошноты и рвоты у беременных. Психогенная рвота Исключены: тошнота (R11) рвота БДУ (R11)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2727, 'Другие расстройства приема пищи', 'F50.8', 2720, 'F50', 0, 'Поедание несъедобного [извращенный аппетит] у взрослых Психогенная потеря аппетита Исключено: поедание несъедобного [извращенный аппетит] у младенцев и детей (F98.3)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2728, 'Расстройство приема пищи неуточненное', 'F50.9', 2720, 'F50', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2729, 'Расстройства сна неорганической этиологии', 'F51', 2719, 'F50-F59', 8, 'Во многих случаях нарушение сна является одним из симптомов других расстройств - психических или соматических. Являются ли нарушения сна у данного пациента самостоятельным состоянием или просто одним из симптомов другого нарушения, классифицированного в рубриках этого или любого другого класса, следует определять на основе клинической картины и течения расстройства, а также с учетом терапевтических заключений у приоритетов, установленных во время консультации. Как правило, если расстройство сна является одним из главных недугов и воспринимается как болезненное состояние само по себе, данный код следует использовать вместе с другими кодами диагнозов психопатологических и патофизиологических расстройств, имеющихся в данном случае. Эта рубрика включает только те нарушения сна, при которых ведущими этиологическими факторами являются эмоциональные причины и которые не не имеют в своей основе идентифицированных в каких-либо рубриках физических нарушений. Исключены: расстройства сна (органической этиологии) (G47.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2730, 'Бессонница неорганической этиологии', 'F51.0', 2729, 'F51', 0, 'Состояние неудовлетворительной продолжительности и/или неудовлетворительного качества сна, которое сохраняется в течение значительного отрезка времени и включает трудности засыпания, трудности оставаться в состоянии сна или раннее окончательное пробуждение. Бессонница является общим симптомом многих психических и соматических расстройств и должна классифицироваться данной подрубрикой в дополнение к основному заболеванию только в том случае, если она доминирует в клинической картине. Исключена: бессонница (органической этиологии) (G47.0)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2731, 'Сонливость [гиперсомния] неорганической этиологии', 'F51.1', 2729, 'F51', 0, 'Гиперсомния определяется как состояние чрезмерной сонливости и приступов сна в дневное время или как затяжной переход к состоянию полного бодрствования при пробуждении. Если в этиологии гиперсомнии отсутствует органический фактор, это состояние обычно связывают с психическим расстройством. Исключены: гиперсомния (органической этиологии) (G47.1) нарколепсия (G47.4)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2732, 'Расстройство режима сна и бодрствования неорганической этиологии', 'F51.2', 2729, 'F51', 0, 'Недостаток синхронности между существующим у пациента режимом сна и бодрствования и тем, какого режима сна и бодрствования требует окружающая его обстановка, результатом чего являются жалобы на бессонницу или гиперсомнию. Психогенная инверсия: . циркадного } . никтогемерального } ритма . сна } Исключены: нарушения цикличности сна и бодрствования (органической этиологии) (G47.2)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2733, 'Снохождение [сомнамбулизм]', 'F51.3', 2729, 'F51', 0, 'Форма измененного сознания, при которой сочетаются состояния сна и бодрствования. Во время эпизода сомнамбулизма человек встает с постели обычно в течение первой трети ночного сна и ходит, демонстрируя низкий уровень осознавания, реактивности и двигательного умения. При пробуждении он обычно не вспоминает случившееся.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2734, 'Ужасы во время сна [ночные ужасы]', 'F51.4', 2729, 'F51', 0, 'Ночные эпизоды крайнего ужаса и паники, сопровождаемые интенсивными восклицаниями, движениями и высоким уровнем вегетативных проявлений. Больной садится или вскакивает с постели обычно в течение первой трети ночного сна с паническим криком. Довольно часто он рвется к двери, как бы пытаясь убежать, хотя очень редко покидает комнату. Воспоминание о случившемся, если оно есть, очень ограничено (обычно один или два фрагмента мысленных воображений).');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2735, 'Кошмары', 'F51.5', 2729, 'F51', 0, 'Переживания во сне перегружены тревогой или страхом. Больной помнит все детали содержания сна. Картины сна очень яркие и обычно включают темы, касающиеся угрозы жизни, безопасности или самооценки. Довольно часто имеет место повторение одних и тех же или подобных пугающих кошмарных сновидений. В течение типичного эпизода данного расстройства выражены вегетативные проявления, но нет заметных восклицаний или движений тела. При пробуждении человек быстро становится бодрым и ориентированным. Ночное тревожное расстройство');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2736, 'Другие расстройства сна неорганической этиологии', 'F51.8', 2729, 'F51', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2737, 'Расстройство сна неорганической этиологии неуточненное', 'F51.9', 2729, 'F51', 0, 'Эмоциональное расстройство сна БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2738, 'Сексуальная дисфункция, не обусловленная органическими нарушениями или болезнями', 'F52', 2719, 'F50-F59', 10, 'Сексуальная дисфункция охватывает различные состояния, в силу которых индивид не способен вступать в сексуальную связь, как бы он того ни желал. Половая реакция является психосоматическим процессом, и обычно и психологический, и соматический процессы причастны к сексуальной дисфункции. Исключен: синдром Дата (F48.8)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2739, 'Отсутствие или потеря сексуального влечения', 'F52.0', 2738, 'F52', 0, 'Потеря сексуального влечения является основной проблемой, и она не вторична по отношению к другим сексуальным проблемам, таким, как недостаток эрекции или диспареуния. Фригидность Сниженное сексуальное влечение');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2740, 'Отвращение к половым сношениям и отсутствие полового удовольствия', 'F52.1', 2738, 'F52', 0, 'удовольствия Перспектива сексуального сношения вызывает такой страх или тревогу, что заставляет избегать полового акта (отвращение к половым сношениям), либо сексуальная реакция оказывается нормальной и испытывается оргазм, но отсутствует соответствующее приятное ощущение (отсутствие полового удовольствия). Ангедония (сексуальная)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2741, 'Недостаточность генитальной реакции', 'F52.2', 2738, 'F52', 0, 'Основной проблемой для мужчин является нарушение эрекции (трудности с возникновением или поддержанием эрекции, достаточной для удовлетворительного полового сношения). У женщин главной проблемой является сухость влагалища или недостаток влагалищной смазки. Расстройство сексуального возбуждения у женщин Эрективное расстройство у мужчин Психогенная импотенция Исключена: импотенция органического происхождения (N48.4)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2742, 'Оргазмическая дисфункция', 'F52.3', 2738, 'F52', 0, 'Оргазм или не возникает, или значительно задерживается. Заторможенный оргазм (у мужчин) (у женщин) Психогенное отсутствие оргазма');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2743, 'Преждевременная эякуляция', 'F52.4', 2738, 'F52', 0, 'Невозможность контролировать эякуляцию в той мере, которая достаточна, чтобы оба партнера получили удовлетворение от полового акта.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2744, 'Вагинизм неорганического происхождения', 'F52.5', 2738, 'F52', 0, 'Спазм мышц тазового дна, окружающих влагалище, который препятствует открытию влагалища. Введение полового члена невозможно или болезненно. Исключен: вагинизм (органический) (N94.2)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2745, 'Диспареуния неорганического происхождения', 'F52.6', 2738, 'F52', 0, 'Диспареуния (болевое ощущение во время полового акта) возникает и у мужчин, и у женщин. Часто диспареуния может быть связана с локальным патологическим процессом, и тогда ее следует классифицировать в соответствии с этим патологическим состоянием. Данную подрубрику следует использовать только в том случае, если отсутствует первичная неорганическая сексуальная дисфункция (например, вагинизм или сухость влагалища). Психогенная диспареуния Исключена: диспареуния (органическая) (N94.1)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2746, 'Повышенное половое влечение', 'F52.7', 2738, 'F52', 0, 'Нимфомания Сатириаз');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2747, 'Другая сексуальная дисфункция, не обусловленная органическим нарушением или болезнью', 'F52.8', 2738, 'F52', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2748, 'Сексуальная дисфункция, не обусловленная органическим нарушением или болезнью, неуточненная', 'F52.9', 2738, 'F52', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2749, 'Психические расстройства и расстройства поведения, связанные с послеродовым периодом, не классифицированные в других рубриках', 'F53', 2719, 'F50-F59', 4, 'Эта рубрика включает только психические расстройства, связанные с послеродовым периодом (возникшие в течение 6 недель после родов), которые не соответствуют критериям, применяемым к расстройствам, классифицированным в каких-либо других рубриках этого класса; это объясняется либо недостаточностью доступной информации, либо тем, что присутствуют дополнительные клинические проявления, что делает неуместной классификацию этих расстройств в каких-либо других рубриках.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2750, 'Легкие психические расстройства и расстройства поведения, связанные с послеродовым периодом, не классифицированные в других рубриках', 'F53.0', 2749, 'F53', 0, 'Депрессия: . постнатальная БДУ . послеродовая БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2751, 'Тяжелые психические расстройства и расстройства поведения, связанные с послеродовым периодом, не классифицированные в других рубриках', 'F53.1', 2749, 'F53', 0, 'Послеродовой психоз БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2752, 'Другие психические расстройства и расстройства поведения, связанные с послеродовым периодом, не классифицированные в других рубриках', 'F53.8', 2749, 'F53', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2753, 'Послеродовое психическое расстройство неуточненное', 'F53.9', 2749, 'F53', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2754, 'Психологические и поведенческие факторы, связанные с нарушениями или болезнями, классифицированными в других рубриках', 'F54', 2719, 'F50-F59', 0, 'Эту рубрику следует использовать для кодирования имеющихся психологических и поведенческих факторов, рассматривающихся как основная этиологическая причина соматических расстройств, которые могут быть отнесены к другим классам болезней. Эти проистекающие психические нарушения обычно слабо выражены и часто устойчивы (например, волнение, эмоциональный конфликт, мрачные предчувствия) и сами по себе не позволяют использовать какую-либо другую рубрику этого класса. Психологические факторы, влияющие на физическое состояние Примерами использования этой рубрики могут служить: . астма F54 и J45.. дерматит F54 и L23-L25 . язва желудка F54 и K25.. слизистый колит F54 и K58.. язвенный колит F54 и K51.. крапивница F54 и L50.При необходимости идентифицировать связанное соматическое нарушение используют дополнительный код. Исключена: головная боль напряженного типа (G44.2)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2755, 'Злоупотребление веществами, не вызывающими зависимость', 'F55', 2719, 'F50-F59', 0, 'Может использоваться широкий спектр медикаментов и народных средств, но особую важность представляют: а) психотропные средства, не приводящие к возникновению зависимости, такие, как антидепрессанты; б) слабительные средства и в) обезболивающие средства, которые могут употребляться без назначения врача (например, аспирин и парацетамол). Постоянное использование этих препаратов часто приводит к ненужным контактам с врачами и другим медицинским персоналом и иногда сопровождается развитием побочных реакций на эти вещества. Попытки разубедить в целесообразности приема этих препаратов или запретить их употребление часто вызывают сопротивление в отношении приема слабительных и обезболивающих средств. Такое сопротивление может иметь место, несмотря на предостережение о возможности (или даже развития) побочных реакций типа почечной дисфункции или нарушений электролитного баланса. Хотя обычно очевидно6 что у пациента имеется выраженная мотивация к приему вещества, симптомы зависимости или абстиненции (классифицированные в рубриках F10-F19), как при использовании психоактивных веществ, не развиваются. Злоупотребление: . антацидными средствами . травами и средствами народной медицины . стероидными или другими гормонами . витаминами Увлечение слабительными средствами Исключено: злоупотребление психоактивными веществами (F10-F19)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2756, 'Поведенческие синдромы, связанные с физиологическими нарушениями и физическими факторами, неуточненные', 'F59', 2719, 'F50-F59', 0, 'Психогенная физиологическая дисфункция БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2757, 'РАССТРОЙСТВА ЛИЧНОСТИ И ПОВЕДЕНИЯ В ЗРЕЛОМ ВОЗРАСТЕ', 'F60-F69', 2428, 'F00-F99', 9, 'Этот блок включает различные состояния и модели поведения клиничес-\nкой значимости, имеющие тенденцию к устойчивости и возникающие как\nвыражение характерного образа жизни индивида и его взаимоотношений\nс окружающими. Некоторые из этих состояний и образцов поведения по-\nявляются рано в ходе индивидуального развития как результат одновре-\nменного воздействия конституциональных факторов и социального опыта,\nв то время как другие приобретаются на более поздних этапах жизни.\nСпецифические расстройства личности (F60.-), смешанные и другие рас-\nстройства личности (F61.-), длительно сохраняющиеся изменения лич-\nности(F62.-) являются глубоко укоренившимися и длительными моделями\nповедения, проявляющимися как негибкая ответная реакция на самые\nразные личные и социальные ситуации. Такие расстройства представляют\nсобой чрезвычайные или значительные отклонения от способа, которым\nобычный человек данного уровня культуры воспринимает, мыслит, чувст-\nвует и особенно общается с окружающими. Такие модели поведения имеют\nтенденцию к устойчивости и охватывают многие области поведения и\nпсихологического функционирования. Данные расстройства часто, но не\nвсегда связаны с субъективными переживаниями различной степени и\nпроблемами социального характера.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2758, 'Специфические расстройства личности', 'F60', 2757, 'F60-F69', 10, 'В эту рубрику отнесены тяжелые расстройства личности и выраженные отклонения в поведении индивида, не являющиеся прямым следствием заболевания, повреждения или другого острого поражения головного мозга либо других психических нарушений. Обычно эти расстройства охватывают несколько сфер личности; почти всегда они тесно связаны с выраженными личными страданиями и социальным распадом. Эти расстройства обычно проявляются в детстве или подростковом возрасте и продолжаются в течение дальнейшей жизни.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2759, 'Параноидное расстройство личности', 'F60.0', 2758, 'F60', 0, 'Расстройство личности, характеризующееся чрезмерной чувствительностью к неудачам, невозможностью прощать обиды, подозрительностью и склонностью к извращению действительности путем истолкования нейтральных или дружеских действий окружающих как враждебных или пренебрежительных. Наблюдаются повторные необоснованные подозрения супруга или сексуального партнера в неверности, воинствующее и упорное сознание собственной правоты. Такие лица склонны к преувеличенной самооценке; часто имеет место преувеличенное самомнение. Личность (расстройство): . экспансивно-параноидная . фанатичная . кверулянтная . параноидная . обидчиво параноидная Исключены: паранойя (F22.0) . кверулянтная (F22.8) параноидный(ая)(ое): . психоз (F22.0) . шизофрения (F20.0) . состояние (F22.0)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2760, 'Шизоидное расстройство личности', 'F60.1', 2758, 'F60', 0, 'Расстройство личности, характеризующееся слабостью привязанностей, социальных и других контактов, склонностью к фантазиям, отшельничеству и самоанализу. Имеет место ограниченная способность выражать чувства и испытывать удовольствие. Исключены: синдром Аспергера (F84.5) бредовое расстройство (F22.0) шизоидное расстройство в детском возрасте (F84.5) шизофрения (F20.-) шизотипическое расстройство (F21)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2761, 'Диссоциальное расстройство личности', 'F60.2', 2758, 'F60', 0, 'Расстройство личности, характеризующееся пренебрежением к социальным обязанностям и черствым равнодушием к окружающим. Наблюдается значительное несоответствие между поведением больного и основными социальными нормами. Поведение с трудом поддается изменению на основе опыта, включая наказание. Больные плохо переносят неудачи и легко поддаются агрессии, включая насилие. Они склонны обвинять других или давать правдоподобные объяснения своему поведению, приводящему их к конфликту с обществом. Личность (расстройство): . аморальная . антисоциальная . асоциальная . психопатическая . социопатическая Исключены: расстройства поведения (F91.-) эмоционально неустойчивое расстройство личности (F60.3)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2762, 'Эмоционально неустойчивое расстройство личности', 'F60.3', 2758, 'F60', 0, 'Расстройство личности, характеризующееся определенной склонностью к импульсивным действиям без учета последствий. Настроение непредсказуемо и капризно. Имеются склонность к вспышкам эмоций и неспособность контролировать взрывчатое поведение. Отмечаются сварливость и конфликтность с окружающими, особенно тогда, когда импульсивные поступки пресекаются и критикуются. Можно выделить два типа расстройства: импульсивный тип, характеризующийся преимущественно эмоциональной нестабильностью и недостатком эмоционального контроля, и пограничный тип, для которого дополнительно характерны расстройство самовосприятия, целей и внутренних устремлений, хроническое ощущение пустоты, напряженные и нестабильные межличностные отношения и тенденция к саморазрушающему поведению, включая суицидальные жесты и попытки. Личность (расстройство): . агрессивная . пограничная . возбудимая Исключено: диссоциальное расстройство личности (F60.2)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2763, 'Истерическое расстройство личности', 'F60.4', 2758, 'F60', 0, 'Расстройство личности, характеризующееся поверхностной и неустойчивой возбудимостью, склонностью к драматизированию, театральности, а также к преувеличенному выражению эмоций, внушаемостью, эгоцентризмом, потаканием своим желаниям, отсутствием внимания к окружающим, легко ранимыми ощущениями и постоянным желанием иметь успех и внимание. Личность (расстройство): . истерическая . психоинфантильная');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2764, 'Ананкастное расстройство личности', 'F60.5', 2758, 'F60', 0, 'Расстройство личности, характеризующееся чувством неуверенности в себе, чрезмерной щепетильностью, сдержанностью и озабоченностью деталями, упрямством, осторожностью и непреклонностью. Могут присутствовать настойчивые или непрошенные мысли или действия, которые не достигают тяжести обессивно-компульсивного расстройства. Личность (расстройство): . компульсивная . обессивная . обессивно-компульсивная Исключено: обсессивно-компульсивное расстройство (F42.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2765, 'Тревожное (уклоняющееся) расстройство личности', 'F60.6', 2758, 'F60', 0, 'Расстройство личности, характеризующееся ощущением внутренней напряженности, наличием мрачных предчувствий, отсутствием ощущения безопасности и комплексом неполноценности. Выражены постоянное сильное желание нравиться и быть признанным, сверхчувствительная реакция на отказы и критику наряду с ограничением личных привязанностей, тенденцией к избеганию некоторых действий путем привычного преувеличения потенциальных опасностей и риска в обыденных ситуациях.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2766, 'Расстройство типа зависимой личности', 'F60.7', 2758, 'F60', 0, 'Расстройство личности, характеризующееся глубоким пассивным подчинением окружающим людям в принятии больших и малых жизненных решений, выраженным страхом перед одиночеством, ощущением беспомощности и некомпетентности, пассивным согласием с желанием старших и окружающих и слабой реакцией на требования повседневной жизни. Отсутствие активности может выражаться в интеллектуальной и эмоциональной сферах; часто выражена тенденция к перекладыванию ответственности на других. Личность (расстройство): . астеническая . неадекватная . пассивная . самоподавляющая');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2767, 'Другие специфические расстройства личности', 'F60.8', 2758, 'F60', 0, 'Личность (расстройство): . эксцентричная . расторможенная ("безудержная") . незрелая . самовлюбленная (нарциссическая) . пассивно-агрессивная . психоневротическая');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2768, 'Расстройство личности неуточненное', 'F60.9', 2758, 'F60', 0, 'Невроз характера БДУ Патологическая личность БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2769, 'Смешанные и другие расстройства личности', 'F61', 2757, 'F60-F69', 0, 'Эта рубрика предназначена для расстройств личности, которые часто причиняют беспокойство, но не проявляют специфической картины симптомов, характеризующих расстройства, классифицированные в рубрике F60.-, поэтому нередко их труднее диагностировать, чем расстройства, кодируемые в рубрике F60.-. Примерами являются: . смешанные расстройства личности с чертами некоторых расстройств, классифицированных в рубрике F60.-, но без доминирующего комплекса симптомов, позволяющего поставить более специфичный диагноз; . причиняющие беспокойство изменения личности, не классифицированные в рубриках F60.- или F62.- и рассматривающиеся как вторичные по отношению к основному диагнозу имеющегося аффективного или тревожного расстройства. Исключены: акцентуированные личностные черты (Z73.1)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2770, 'Стойкие изменения личности, не связанные с повреждением или болезнью головного мозга', 'F62', 2757, 'F60-F69', 4, 'Расстройства личности и поведения в зрелом возрасте, которые возникли у человека, не имевшего в прошлом расстройств личности, пережившего катастрофу или чрезмерно длительный стресс, или перенесшего тяжелое психическое заболевание. Диагнозы этой рубрики следует ставить только тогда, когда очевидно наличие определенных и продолжительных изменений в личной модели восприятия, отношения и мыслей относительно окружающей обстановки и лично себя. Изменение личности должно быть значительным и должно ассоциироваться с негибким, не соответствующим нормам поведением, не отмечавшимся ранее. Изменение не должно быть непосредственным проявлением имеющегося другого психического расстройства или остаточным симптомом какого-либо предшествующего психического заболевания. Исключено: расстройство личности и поведения, обусловленное болезнью, повреждением или дисфункцией головного мозга (F07.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2771, 'Стойкое изменение личности после переживания катастрофы', 'F62.0', 2770, 'F62', 0, 'Длительно сохраняющееся (по крайней мере два года) изменение личности, вызванное действием катастрофического стресса. Стресс может быть таким экстремальным, что нет необходимости принимать во внимание индивидуальную ранимость для того, чтобы объяснить глубину его воздействия на личность. Психическое расстройство характеризуется враждебным или подозрительным отношением к окружающему, социальной самоизоляцией, чувством пустоты и безысходности, стойким ощущением "пребывания на грани", как это отмечается в случае постоянных угроз, и отчужденностью. Этому типу изменения личности может предшествовать расстройство, вызванное травматическим стрессом (F43.1). Изменение личности после: . пребывания в концентрационном лагере . бедствия . длительного: . плена с угрозой быть убитым . нахождения в ситуации, угрожающей жизни, типа быть жертвой терроризма . пыток Исключено: посттравматическое стрессовое расстройство (F43.1)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2772, 'Стойкое изменение личности после психического заболевания', 'F62.1', 2770, 'F62', 0, 'Изменение личности, сохраняющееся по крайней мере два года, которое вызвано травмирующим влиянием страдания от тяжелой психической болезни. Изменение не может быть объяснено предшествующим расстройством личности. Его следует дифференцировать от остаточных проявлений шизофрении и других состояний неполного выздоровления после предшествующей психической болезни. Это расстройство характеризуется чрезмерной зависимостью и нуждаемостью в других. Убежденность человека в том, что болезнь изменила его и оставила на нем свое клеймо, приводит к неспособности формировать и поддерживать тесные доверительные межличностные отношения и ведет к социальной изоляции. Наблюдается пассивность, ограниченность интересов и слабая вовлекаемость в активное проведение досуга. Устойчивы жалобы на плохое самочувствие, которые могут быть связаны с ипохондрическими претензиями и болезненным поведением. Отмечается пониженное или неустойчивое настроение, не являющееся следствием текущего психического расстройства или предшествующей психической болезни с остаточными аффективными симптомами, а также давнишние проблемы социального и профессионального функционирования.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2773, 'Другие стойкие изменения личности', 'F62.8', 2770, 'F62', 0, 'Хронический болевой личностный синдром');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2774, 'Стойкое изменение личности неуточненное', 'F62.9', 2770, 'F62', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2775, 'Расстройства привычек и влечений', 'F63', 2757, 'F60-F69', 6, 'Эта рубрика включает некоторые расстройства поведения, которые не классифицируются в других рубриках. Эти расстройства характеризуются повторными действиями, которые не имеют ясно выраженной рациональной мотивации, не могут контролироваться и обычно наносят вред самому больному и окружающим. Пациент говорит, что его поведение связано с влечением к действию. Причина этих расстройств не установлена, и они сгруппированы вместе на основе ярко выраженной тождественности в их описании, а не из-за наличия у них каких-либо известных других важных общих особенностей. Исключены: привычное чрезмерное употребление алкоголя или психоактивных веществ (F10-F19) расстройство влечений и привычек, затрагивающих сексуальное поведение (F65.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2776, 'Патологическое влечение к азартным играм', 'F63.0', 2775, 'F63', 0, 'Суть расстройства заключается в частых повторных эпизодах азартной игры, которые доминируют в жизни пациента в ущерб социальным, профессиональным, материальным и семейным ценностям и обязательствам. Навязчивое влечение к азартным играм Исключены: пристрастие к азартным играм лиц с маниакальным эпизодом (F30.-) склонность к азартным играм и пари БДУ (Z72.6) склонность к азартным играм при диссоциальном расстройстве личности (F60.2)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2777, 'Патологическое влечение к поджогам [пиромания]', 'F63.1', 2775, 'F63', 0, 'Расстройство, характеризующееся многочисленными актами поджогов имущества или других объектов или попытками поджогов, которые совершаются без какой-либо явной мотивации, а также увлеченностью всем, что связано с огнем и горением. Такое поведение часто связано с ощущением возрастающего напряжения перед этим действием и сильным возбуждением сразу же после него. Исключены: поджог (совершенный): . взрослым человеком с диссоциальным расстройством личности (F60.2) . как повод для наблюдения за лицом с подозрением на психическое расстройство (Z03.2) при: . интоксикации алкоголем или психоактивным веществом (F10-F19 с общим четвертым знаком .0) . расстройствах поведения (F91.-) . органических психических расстройствах (F00-F09) . шизофрении (F20.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2778, 'Патологическое влечение к воровству [клептомания]', 'F63.2', 2775, 'F63', 0, 'Расстройство, характеризующееся повторными безуспешными попытками человека противостоять желанию украсть какой-либо предмет, не являющийся для него необходимым или представляющим денежную ценность. Украденные предметы, напротив, могут быть испорчены, отданы задаром или припрятаны. Такое поведение обычно сопровождается возрастающим чувством напряжения до совершения кражи и ощущением удовлетворения в процессе кражи или сразу же после нее. Исключены: депрессивное расстройство с воровством (F31-F33) органические психические расстройства (F00-F09) ограбление магазина как повод для наблюдения за лицом с подозрением на психическое расстройство (Z03.2)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2779, 'Трихотилломания', 'F63.3', 2775, 'F63', 0, 'Расстройство, характеризующееся заметной потерей волос вследствие повторных безуспешных попыток подавить желание их выдергивать. Выдергиванию волос обычно предшествует растущее напряжение, а акт выдергивания сопровождается расслаблением и чувством удовлетворения. Этот диагноз не следует ставить, если имеется ранее существовавшее воспаление кожи или если выдергивание волос является реакцией на бред или галлюцинацию. Исключено: стереотипное двигательное расстройство с выдергиванием волос (F98.4)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2780, 'Другие расстройства привычек и влечений', 'F63.8', 2775, 'F63', 0, 'Другие формы постоянно повторяющегося неадекватного поведения, которые не являются вторичными по отношению к диагностированному психическому синдрому и при которых очевидно, что пациент производит повторяющиеся безуспешные попытки подавить влечение к такому поведению. Человек испытывает продромальный период напряжения, затем возникает ощущение облегчения в процессе этого действия. Перемежающееся расстройство взрывного характера');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2781, 'Расстройство привычек и влечений неуточненное', 'F63.9', 2775, 'F63', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2782, 'Расстройства половой идентификации', 'F64', 2757, 'F60-F69', 5, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2783, 'Транссексуализм', 'F64.0', 2782, 'F64', 0, 'Желание жить и восприниматься окружающими как лицо противоположного пола, обычно сопровождаемое ощущением дискомфорта от своего анатомического пола или чувством неуместности своей половой принадлежности. Желание подвергнуться хирургическому вмешательству или получить гормональное лечение с тем, чтобы достичь, насколько это возможно, соответствия предпочитаемому полу.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2784, 'Трансвестизм двойной роли', 'F64.1', 2782, 'F64', 0, 'Периодическое ношение одежды противоположного пола для того, чтобы насладиться временным участием в жизни противоположного пола, но без какого-либо желания изменить свой пол, в том числе и хирургическим путем, и без полового возбуждения, сопровождающего переодевание. Расстройство половой идентификации в юности или зрелом возрасте не транссексуального типа Исключен: фетишистский трансвестизм (F65.1)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2785, 'Расстройство половой идентификации в детском возрасте', 'F64.2', 2782, 'F64', 0, 'Расстройство, первоначально обычно проявляющееся в раннем детстве (и всегда задолго до пубертатного периода) и характеризующееся устойчивым и сильным страданием по поводу своего пола одновременно с сильным желанием быть лицом другого пола или настойчивым требованием признать его таковым. имеются постоянная озабоченность одеждой и занятиями лиц другого пола и отказ от особенностей своего пола. Этот диагноз должен ставиться лишь при глубоком нарушении половой идентификации, наличие черт сорванца у девочки или девичьих черт у мальчика недостаточно для его постановки. Расстройство половой идентификации у лиц, достигших половой зрелости или входящих в пубертатный период, следует классифицировать не этой рубрикой, а рубрикой F66.-. Исключены: эгодистоническая половая ориентация (F66.1) расстройство сексуальной сформированности (F66.0)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2786, 'Другое расстройство половой идентификации', 'F64.8', 2782, 'F64', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2787, 'Расстройство половой идентификации, неуточненное', 'F64.9', 2782, 'F64', 0, 'Отклонение от поведения, свойственного данному полу БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2788, 'Расстройства сексуального предпочтения', 'F65', 2757, 'F60-F69', 9, 'Включены: парафилии');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2789, 'Фетишизм', 'F65.0', 2788, 'F65', 0, 'Ориентированность на некоторые неживые объекты как стимуляторы полового возбуждения и полового удовлетворения. Многие фетиши являются дополнениями к человеческому телу (например, предметы одежды или обуви). Другими распространенными примерами фетишей являются некоторые специфические материалы (например, резина, пластик или кожа). Фетишные объекты варьируются в своей значимости для индивида. Иногда они просто способствуют усилению сексуального возбуждения, достигаемого обычным способом (например, одевание партнера в специфическую одежду).');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2790, 'Фетишистский трансвестизм', 'F65.1', 2788, 'F65', 0, 'Надевание одежды противоположного пола главным образом для того, чтобы добиться сексуального возбуждения и вызвать образ индивида противоположного пола. Фетишистский трансвестизм отличается от транссексуального трансвестизма своей ясно выраженной связью с сексуальным возбуждением и сильным желанием освободиться от одежды при наступлении оргазма и последующего сексуального расслабления. Расстройство может оказываться ранней стадией развития транссексуализма. Трансвестистский фетишизм');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2791, 'Эсгибиционизм', 'F65.2', 2788, 'F65', 0, 'Повторная или устойчивая тенденция показывать свои половые органы посторонним лицам (обычно противоположного пола) или людям в общественных местах без намерения вступить в близкий контакт. Обычно, но не всегда отмечается сексуальное возбуждение в момент показа половых органов, и этот акт чаще всего сопровождается мастурбацией.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2792, 'Вуайеризм', 'F65.3', 2788, 'F65', 0, 'Повторная или устойчивая тенденция подсматривать за людьми в момент совершения ими сексуальных или интимных действий, таких, как раздевание. Это производится втайне от человека, за которым наблюдают, и обычно ведет к сексуальному возбуждению и мастурбации.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2793, 'Педофилия', 'F65.4', 2788, 'F65', 0, 'Сексуальная тяга к детям (мальчикам, девочкам или к тем и другим), обычно препубертатного или раннего пубертатного возраста.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2794, 'Садомазохизм', 'F65.5', 2788, 'F65', 0, 'Сексуальная тяга к действиям, которые связаны с причинением боли или вызыванием унижения и зависимости. Если индивид предпочитает быть объектом такой стимуляции, речь идет о мазохизме, если исполнителем ее, то о садизме. Часто индивид достигает сексуального возбуждения и от садистских, и от мазохистских действий. Мазохизм Садизм');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2795, 'Множественные расстройства сексуального предпочтения', 'F65.6', 2788, 'F65', 0, 'Иногда у одного пациента имеет место несколько сексуальных извращений, и их трудно ранжировать. Наиболее частой комбинацией является фетишизм, трансвестизм и садомазохизм.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2796, 'Другие расстройства сексуального предпочтения', 'F65.8', 2788, 'F65', 0, 'Разнообразие других форм извращенных сексуальных влечений и действий, включая осуществление "грязных" телефонных звонков; стремление притиснуться к человеку в переполненных толпой общественных местах с тем, чтобы вызвать половое возбуждение; сексуальные действия с животными; использование удушения или аноксии для увеличения сексуального возбуждения. Фроттаризм [фроттаж] Некрофилия');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2797, 'Расстройство сексуального предпочтения неуточненное', 'F65.9', 2788, 'F65', 0, 'Сексуальная девиация БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2798, 'Психологические и поведенческие расстройства, связанные с половым развитием и ориентацией', 'F66', 2757, 'F60-F69', 5, 'Примечание. Сама по себе сексуальная ориентация не рассматривается как расстройство.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2799, 'Расстройство сексуального созревания', 'F66.0', 2798, 'F66', 0, 'Пациент страдает от неопределенности своей половой принадлежности или сексуальной ориентации, и это является причиной тревоги и депрессии. Чаще всего это расстройство возникает у подростков, которые не уверены, являются ли они в своей ориентации гомосексуалами, гетеросексуалами или бисексуалами, либо у индивидов, которые после периода явно стабильной сексуальной ориентации (часто в период длительных связей) обнаруживают, что их сексуальная ориентация изменяется.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2800, 'Эгодистоническая половая ориентация', 'F66.1', 2798, 'F66', 0, 'Половая принадлежность и сексуальное влечение (гетеросексуальное, гомосексуальное, бисексуальное или препубертатное) не вызывают сомнений, но индивид желает это изменить в связи с присоединившимися психологическими нарушениями и расстройствами поведения и может добиваться лечения для такого изменения.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2801, 'Расстройство сексуальных отношений', 'F66.2', 2798, 'F66', 0, 'Половая принадлежность или сексуальная ориентация (гетеросексуальная, гомосексуальная или бисексуальная) являются причиной трудностей в формировании и поддержании связи с сексуальным партнером.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2802, 'Другие расстройства психосексуального развития', 'F66.8', 2798, 'F66', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2803, 'Расстройство психосексуального развития неуточненное', 'F66.9', 2798, 'F66', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2804, 'Другие расстройства личности и поведения в зрелом возрасте', 'F68', 2757, 'F60-F69', 3, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2805, 'Преувеличение соматической симптоматики по психологическим причинам', 'F68.0', 2804, 'F68', 0, 'Соматические симптомы, которые соответствуют и вызваны подтвержденным физическим нарушением, болезнью или снижением физических возможностей, становятся преувеличенными или затяжными вследствие психологического состояния пациента. Пациент обычно страдает от боли или снижения дееспособности и часто полностью поглощен своей тревогой (которая может быть оправданной) о возможности продолжения или прогрессирования боли и снижения дееспособности. Компенсационный невроз');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2806, 'Умышленное вызывание или симулирование симптомов или инвалидности физического или психологического характера [поддельное нарушение]', 'F68.1', 2804, 'F68', 0, 'Пациент симулирует симптомы неоднократно по не вполне понятной причине и может даже нанести себе вред, чтобы вызвать признаки нарушений. Мотивация является неясной и внутренне, по-видимому, оправдана с целью взятия на себя роли больного. Расстройство часто сочетается с заметными расстройствами личности и взаимоотношений. Синдром "госпитальной блохи" Синдром Мюнхгаузена Кочующий пациент Исключено: искусственный [артифициальный] дерматит (L98.1) личность, симулирующая болезнь (с очевидной мотивацией) (Z76.5)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2807, 'Другие уточненные расстройства личности и поведения в зрелом возрасте', 'F68.8', 2804, 'F68', 0, 'Нарушение характера БДУ Расстройство взаимоотношений БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2808, 'Расстройство личности и поведения в зрелом возрасте неуточненное', 'F69', 2757, 'F60-F69', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2809, 'УМСТВЕННАЯ ОТСТАЛОСТЬ', 'F70-F79', 2428, 'F00-F99', 6, 'Состояние задержанного или неполного умственного развития, которое\nхарактеризуется прежде всего снижением навыков, возникающих в про-\nцессе развития, и навыков, которые определяют общий уровень интел-\nлекта (т.е. познавательных способностей, языка, моторики, социаль-\nной дееспособности). Умственная отсталость может возникнуть на фо-\nне другого психического или физического нарушения либо без него.\nСтепень умственной отсталости обычно оценивается стандартизованны-\nми тестами, определяющими состояние пациента. Они могут быть до-\nполнены шкалами, оценивающими социальную адаптацию в данной окру-\nжающей обстановке. Эти методики обеспечивают ориентировочное опре-\nделение степени умственной отсталости. Диагноз будет также зави-\nсеть от общей оценки интеллектуального функционирования по выяв-\nленному уровню навыков.\nИнтеллектуальные способности и социальная адаптация со временем\nмогут измениться, однако достаточно слабо. Это улучшение может\nявиться результатом тренировки и реабилитации. Диагноз должен ба-\nзироваться на достигнутом на настоящий момент уровне умственной\nдеятельности.\nДля идентифицикации степени умственной недостаточности рубрики\nF70-F79 употребляются со следующим четвертым знаком:\nПри необходимости идентифицировать состояния, связанные с умственной\nотсталостью, такие, как аутизм, другие нарушения развития, эпилеп-\nсия, расстройства поведения или тяжелый физический недостаток, ис-\nпользуют дополнительный код.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2810, 'Умственная отсталость легкой степени', 'F70', 2809, 'F70-F79', 4, 'Ориентировочный IQ составляет 50-69 (в зрелом возрасте умственное развитие соответствует развитию в возрасте 9-12 лет). Вероятны некоторые трудности обучения в школе. Многие взрослые будут в состоянии работать, поддерживать нормальные социальные отношения и вносить вклад в общество. Включены: слабоумие');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2811, 'Умственная отсталость легкой степени с указанием на отсутствие или слабую выраженность нарушения поведения', 'F70.0', 2810, 'F70', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2812, 'Умственная отсталость легкой степени: значительное нарушение поведения, требующее ухода и лечения', 'F70.1', 2810, 'F70', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2813, 'Умственная отсталость легкой степени: другие нарушения поведения', 'F70.8', 2810, 'F70', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2814, 'Умственная отсталость легкой степени без указаний на нарушение поведения', 'F70.9', 2810, 'F70', 0, 'слабо выраженная умственная субнормальность');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2815, 'Умственная отсталость умеренная', 'F71', 2809, 'F70-F79', 4, 'Ориентировочный IQ колеблется от 35 до 49 (в зрелом возрасте умственное развитие соответствует развитию в возрасте 6-9 лет). Вероятно заметное отставание в развитии с детства, но большинство может обучаться и достичь определенной степени независимости в самообслуживании, приобрести адекватные коммуникационные и учебные навыки. Взрослые будут нуждаться в разных видах поддержки в быту и на работе. Включена: умственная субнормальность средней тяжести');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2816, 'Умственная отсталость умеренная с указанием на отсутствие или слабую выраженность нарушения поведения', 'F71.0', 2815, 'F71', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2817, 'Умственная отсталость умеренная: значительное нарушение поведения, требующее ухода и лечения', 'F71.1', 2815, 'F71', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2818, 'Умственная отсталость умеренная: другие нарушения поведения', 'F71.8', 2815, 'F71', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2819, 'Умственная отсталость умеренная без указаний на нарушение поведения', 'F71.9', 2815, 'F71', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2820, 'Умственная отсталость тяжелая', 'F72', 2809, 'F70-F79', 4, 'Ориентировочный IQ колеблется от 20 до 34 (в зрелом возрасте умственное развитие соответствует развитию в возрасте 3-6 лет). Вероятна необходимость постоянной поддержки. Включена: резко выраженная умственная субнормальность');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2821, 'Умственная отсталость тяжелая с указанием на отсутствие или слабую выраженность нарушения поведения', 'F72.0', 2820, 'F72', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2822, 'Умственная отсталость тяжелая: значительное нарушение поведения, требующее ухода и лечения', 'F72.1', 2820, 'F72', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2823, 'Умственная отсталость тяжелая: другие нарушения поведения', 'F72.8', 2820, 'F72', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2824, 'Умственная отсталость тяжелая без указаний на нарушение поведения', 'F72.9', 2820, 'F72', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2825, 'Умственная отсталость глубокая', 'F73', 2809, 'F70-F79', 4, 'Ориентировочный IQ ниже 20 (в зрелом возрасте умственное развитие ниже развития в трехлетнем возрасте). Результатом является тяжелое ограничение самообслуживания, коммуникабельности и подвижности, а также повышенная сексуальность. Включена: глубокая умственная субнормальность');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2826, 'Умственная отсталость глубокая с указанием на отсутствие или слабую выраженность нарушения поведения', 'F73.0', 2825, 'F73', 0, NULL);
