INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2926, 'Менингит при других инфекционных и паразитарных болезнях, классифицированных в других рубриках', 'G02*', 2917, 'G00-G09', 3, 'Исключены: менингоэнцефалит и менингомиелит при инфекционных и паразитарных болезнях, классифицированных в других рубриках (G05.1-G05.2*)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2927, 'Менингит при вирусных болезнях, классифицированных в других рубриках', 'G02.0*', 2926, 'G02*', 0, 'Менингит (вызванный вирусом): . аденовирусный (А87.1+) . энтеровирусный (А87.0+) . простого герпеса (В00.3+) . инфекционного мононуклеоза (В27.-+) . кори (В05.1+) . эпидемического паротита (В26.1+) . краснухи (В06.0+) . ветряной оспы (В01.0+) . опоясывающего лишая (В02.1+)');
