INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2930, 'Менингит, обусловленный другими и неуточненными причинами', 'G03', 2917, 'G00-G09', 5, 'Включены: арахноидит } лептоменингит } вследствие других и неуточненных менингит } причин пахименингит } Исключены: менингоэнцефалит (G04.-) менингомиелит (G04.-)');
