INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2944, 'Энцефалит, миелит и энцефаломиелит при вирусных болезнях, классифицированных в других рубриках', 'G05.1*', 2942, 'G05*', 0, 'Энцефалит, миелит или энцефаломиелит (при): . аденовирусных (А85.1+) . цитомегаловирусный (В25.8+) . энтеровирусный (А85.0+) . простом герпесе (В00.4+) . гриппе (J10.8+, J11.8+) . кори (В05.0+) . эпидемическом паротите (В26.2+) . после ветряной оспы (В01.1+) . краснухе (В06.0+) . опоясывающем лишае (В02.1+)');
