INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2947, 'Внутричерепной и внутрипозвоночный абсцесс и гранулема', 'G06', 2917, 'G00-G09', 3, 'При необходимости идентифицировать инфекционный агент используют дополнительный код (В95-В97).');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(2948, 'Внутричерепной абсцесс и гранулема', 'G06.0', 2947, 'G06', 0, 'Абсцесс (эмболический): . головного мозга [любой части] . мозжечковый . церебральный . отогенный Внутричерепной(ая) абсцесс или гранулема: . эпидуральный(ая) . экстрадуральный(ая) . субдуральный(ая)');
