INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(3208, 'Мышечная дистрофия', 'G71.0', 3207, 'G71', 0, 'Мышечная дистрофия: . аутосомная рецессивная детского типа, напоминающая дистрофию Дюшенна или Беккера . доброкачественная [Беккера] . доброкачественная лопаточно-перонеальная с ранними контрактурами [Эмери-Дрейфуса] . дистальная . плечелопаточно-лицевая . конечностно-поясная . глазных мышц . глазоглоточная [окулофарингеальная] . лопаточно-малоберцовая . злокачественная [Дюшенна] Исключены: врожденная мышечная дистрофия: . БДУ (G71.2) . с уточненными морфологическими поражениями мышечного волокна (G71.2)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(3209, 'Миотонические расстройства', 'G71.1', 3207, 'G71', 0, 'Дистрофия миотоническая [Штейнера] Миотония: . хондродистрофическая . лекарственная . симптоматическая Миотония врожденная: . БДУ . доминантное наследование [Томсена] . рецессивное наследование [Беккера] Нейромиотония [Исаакса] Парамиотония врожденная Псевдомиотония При необходимости идентифицировать лекарственное средство, вызвавшее поражение, используют дополнительный код внешних причин (класс ХХ).');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(3210, 'Врожденные миопатии', 'G71.2', 3207, 'G71', 0, 'Врожденная мышечная дистрофия: . БДУ . со специфическими морфологическими поражениями мышечного волокна Болезнь: . цетрального ядра . миниядерная . мультиядерная Диспропорция типов волокон Миопатия: . миотубулярная (центроядерная) . немалинная [болезнь немалинного тела]');
