INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(3312, 'Миелопатия при болезнях, классифицированных в других рубриках', 'G99.2*', 3309, 'G99*', 0, 'Синдромы сдавления передней спинальной и позвоночной артерии (M47.0*) Миелопатия при: . поражениях межпозвоночных дисков (M50.0+, M51.0+) . опухолевом поражении (C00-D48+) . спондилезе (M47.-+)');
