INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(3612, 'Ухудшение зрения средней степени, бинокулярное', 'H54.2', 3609, 'H54', 0, 'Нарушение зрения категории 1 или 2 обоих глаз');
