INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(3633, 'БОЛЕЗНИ УХА И СОСЦЕВИДНОГО ОТРОСТКА', 'H60-H95', NULL, NULL, 4, 'Исключены: отдельные состояния, возникающие в перинатальном периоде (P00-P96) некоторые инфекционные и паразитарные болезни (A00-B99) осложнения беременности, родов и послеродового периода (O00-O99) врожденные аномалии, деформации и хромосомные нарушения (Q00-Q99) болезни эндокринной системы, расстройства питания и нарушения обмена веществ (E00-E90) травмы, отравления и некоторые другие последствия воздействия внешних причин (S00-T98) новообразования (C00-D48) симптомы, признаки и отклонения от нормы, выявленные при клинических и лабораторных исследованиях, не классифицированные в других рубриках (R00-R99)\nЭтот класс содержит следующие блоки:\nH60-H62 Болезни наружного уха\nH65-H75 Болезни среднего уха и сосцевидного отростка\nH80-H83 Болезни внутреннего уха\nH90-H95 Другие болезни уха\nЗвездочкой отмечены следующие категории:\nH62* Поражения наружного уха при болезнях, классифицированных в других рубриках\nH67* Средний отит при болезнях, классифицированных в других рубриках\nH75* Другие поражения среднего уха и сосцевидного отростка при болезнях, классифицированных в других рубриках\nH82* Вестибулярные синдромы при болезнях, классифицированных в других рубриках\nH94* Другие поражения уха при болезнях, классифицированных в других рубриках');
