INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(3776, 'Ревматическая лихорадка с вовлечением сердца', 'I01', 3774, 'I00-I02', 5, 'Исключены: хронические болезни сердца ревматического происхождения (I05-I09) без одновременного развития острого ревматического процесса или без явлений активизирования или рецидива этого процесса. При появлении сомнений относительно активности ревматического процесса к моменту смерти следует обратиться к рекомендациям и правилам кодирования смертности, изложенным в т. 2.');
