INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(3836, 'ИШЕМИЧЕСКАЯ БОЛЕЗНЬ СЕРДЦА', 'I20-I25', 3773, 'I00-I99', 6, 'Примечание. Для статистики заболеваемости определение "продолжительность", использованное в рубрике I21-I25, включает отрезок времени от начала ишемического приступа до поступления больного в медицинское учреждение. Для статистики смертности оно охватывает отрезок времени от начала ишемического приступа до наступления смертельного исхода.\nВключена: с упоминанием о гипертензии (I10-I15)\nПри необходимости указать наличие гипертензии используют дополнительный код.');
