INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(4241, 'Острый синусит', 'J01', 4239, 'J00-J06', 7, 'Включены: абсцесс } эмпиема } острый(ая)(ое), синуса инфекция } (придаточного) (носового) воспаление } нагноение } При необходимости идентифицировать инфекционный агент используют дополнительный код (B95-B97). Исключен: синусит хронический или БДУ (J32.-)');
