INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(4525, 'БОЛЕЗНИ ОРГАНОВ ПИЩЕВАРЕНИЯ', 'K00-K93', NULL, NULL, 10, 'Исключены: отдельные состояния, возникающие в перинатальном периоде (P00-P96) некоторые инфекционные и паразитарные болезни (A00-B99) осложнения беременности, родов и послеродового периода (O00-O99) врожденные аномалии, деформации и хромосомные нарушения (Q00-Q99) болезни эндокринной системы, расстройства питания и нарушения обмена веществ (E00-E90) травмы, отравления и некоторые другие последствия воздействия внешних причин (S00-T98) новообразования (C00-D48) симптомы, признаки и отклонения от нормы, выявленные при клинических и лабораторных исследованиях, не классифицированные в других рубриках (R00-R99)\n\nЭтот класс содержит следующие блоки:\nK00-K04 Болезни полости рта, слюнных желез и челюстей\nK20-K31 Болезни пищевода, желудка и двенадцатиперстной кишки\nK35-K38 Болезни аппендикса [червеобразного отростка]\nK40-K46 Грыжи\nK50-K52 Неинфекционные энтериты и колиты\nK55-K63 Другие болезни кишечника\nK65-K67 Болезни брюшины\nK70-K77 Болезни печени\nK80-K87 Болезни желчного пузыря, желчевыводящих путей и поджелудочной железы\nK90-K93 Другие болезни органов пищеварения\n\nЗвездочкой отмечены следующие категории:\nK23* Поражения пищевода при болезнях, классифицированных в других рубриках\nK67* Поражения брюшины при инфекционных болезнях, классифицированных в других рубриках\nK77* Поражения печени при болезнях, классифицированных в других рубриках\nK87* Поражения желчного пузыря, желчевыводящих путей и поджелудочной железы при болезнях, классифицированных в других рубриках\nK93* Поражения других органов пищеварения при болезнях, классифицированных в других рубриках');
