INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(5012, 'БОЛЕЗНИ КОЖИ И ПОДКОЖНОЙ КЛЕТЧАТКИ', 'L00-L99', NULL, NULL, 8, 'Исключено: отдельные состояния, возникающие в перинатальном периоде (P00-P96) некоторые инфекционные и паразитарные болезни (A00-B99) осложнения беременности, родов и послеродового периода (O00-O99) врожденные аномалии, деформации и хромосомные нарушения (Q00-Q99) болезни эндокринной системы, расстройства питания и нарушения обмена веществ (E00-E90) травмы, отравления и некоторые другие последствия воздействия внешних причин (S00-T98) липомеланотический ретикулез (I89.8) новообразования (C00-D48) симптомы, признаки и отклонения от нормы, выявленные при клинических и лабораторных исследованиях, не классифицированные в других рубриках (R00-R99) системные нарушения соединительной ткани (M30-M36)\nЭтот класс содержит следующие блоки:\nL00-L04 Инфекции кожи и подкожной клетчатки\nL10-L14 Буллезные нарушения\nL20-L30 Дерматит и экзема\nL40-L45 Папулосквамозные нарушения\nL50-L54 Крапивница и эритема\nL55-L59 Болезни кожи и подкожной клетчатки, связанные с излучением\nL60-L75 Болезни придатков кожи\nL80-L99 Другие болезни кожи и подкожной клетчатки\nЗвездочкой отмечены следующие категории:\nL14* Буллезные нарушения кожи при болезнях, классифицированных в других рубриках\nL45* Папулосквамозные нарушения при болезнях, классифицированных в других рубриках\nL54* Эритема при болезнях, классифицированных в других рубриках\nL62* Изменения ногтей при болезнях, классифицированных в других рубриках\nL86* Кератодермии при болезнях, классифицированных в других рубриках\nL99* Другие нарушения кожи и подкожной клетчатки при болезнях, классифицированных в других рубриках');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(5013, 'ИНФЕКЦИИ КОЖИ И ПОДКОЖНОЙ КЛЕТЧАТКИ', 'L00-L08', 5012, 'L00-L99', 7, 'При необходимости идентифицировать инфекционный агент используют\nдополнительный код (B95-B97).\nИсключены: гордеолум (H00.0) инфекционный дерматит (L30.3) местные инфекции кожи, классифицированные в классе I, такие как: . рожа (A46) . эризипелоид (A26.-) . герпетическая вирусная инфекция [herpes simplex] (B00.-) . аногенитальная (A60.-) . контагиозный моллюск (B08.1) . микозы (B35-B49) . педикулез, акариаз и другие инфестации (B85-B89) . вирусные бородавки (B07) панникулит: . БДУ (M79.3) . волчаночный (L93.2) . шеи и спины (M54.0) . рецидивирующий [Вебера-Крисчена] (M35.6) трещина спайки губ [заеда] (вследствие): . БДУ (K13.0) . кандидоза (B37.-) . недостаточности рибофлавина (E53.0) пиогенная гранулема (L98.0) опоясывающий лишай [zoster] (B02.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(5014, 'Синдром стафилококкового поражения кожи в виде ожогоподобных пузырей', 'L00', 5013, 'L00-L08', 0, 'Пузырчатка новорожденного Болезнь Риттера Исключен: токсический эпидермальный некролиз [Лайелла] (L51.2)');
