INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(6027, 'Другие приобретенные деформации костно-мышечной системы и соединительной ткани', 'M95', 6026, 'M95-M99', 8, 'Исключены: приобретенное(ые): . отсутствие конечностей и органов (Z89-Z90) . деформации конечностей (M20-M21) врожденные аномалии и деформации костно-мышечной системы (Q65-Q79) деформирующие дорсопатии (M40-M43) челюстно-лицевые аномалии [включая аномалии прикуса] (K07.-) костно-мышечные нарушения после медицинских процедур (M96.-)');
