INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(6043, 'Перелом после установки ортопедического имплантата суставного протеза или костной пластинки', 'M96.6', 6036, 'M96', 0, 'Исключены: осложнения, связанные с внутренними ортопеди ческими устройствами, имплантатами или трансплантатами (T84.-)');
