INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(6071, 'Быстро прогрессирующий нефритический синдром', 'N01', 6059, 'N00-N08', 10, '[подрубрики см. на с. 3] Включены: быстро прогрессирующая(ий): . гломерулярная болезнь . гломерулонефрит . нефрит Исключен: нефритический синдром БДУ (N05.-)');
