INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(6571, 'БЕРЕМЕННОСТЬ, РОДЫ И ПОСЛЕРОДОВОЙ ПЕРИОД', 'O00-O99', NULL, NULL, 8, 'Исключены: болезнь, вызванная вирусом иммунодефицита человека [ВИЧ] (B20-B24) травмы, отравления и другие последствия воздействия внешних причин (S00-T98) психические расстройства и расстройства поведения, связанные с послеродовым периодом (F53.-) акушерский столбняк (A34) послеродовой некроз гипофиза (E23.0) послеродовая остеомаляция (M83.0) наблюдение за течением: . беременности у женщины, подвергающейся высокому риску (Z35.-) . нормальной беременности (Z34.-)\nЭтот класс содержит следующие блоки:\nO00-O08 Беременность с абортивным исходом\nO10-O16 Отеки, протеинурия и гипертензивные расстройства во время беременности, родов и в послеродовом периоде\nO20-O29 Другие болезни матери, преимущественно связанные с беременностью\nO30-O48 Медицинская помощь матери в связи с состоянием плода, амниотической полости и возможными трудностями родоразрешения\nO60-O75 Осложнения родов и родоразрешения\nO38-O84 Родоразрешение\nO85-092 Осложнения, связанные преимущественно с послеродовым периодом\nO95-O99 Другие акушерские состояния, не классифицированные в других рубриках');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(6572, 'БЕРЕМЕННОСТЬ С АБОРТИВНЫМ ИСХОДОМ', 'O00-O08', 6571, 'O00-O99', 9, 'Исключена: продолжающаяся беременность при многоплодном зачатии после аборта одного или более чем одного плода (O31.1)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(6573, 'Внематочная [эктопическая] беременность', 'O00', 6572, 'O00-O08', 5, 'Включена: внематочная беременность с разрывом При необходимости идентифицировать любое связанное с этим осложнение используют дополнительный код рубрики O08.-.');
