INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14909, 'Смерть от последствий акушерской причины, неуточненных', 'O97.9', 7046, 'O97', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7047, 'Инфекционные и паразитарные болезни матери, классифицированные в других рубриках, но осложняющие беременность, роды и послеродовой период', 'O98', 7043, 'O94-O99', 10, 'Включены: перечисленные состояния, осложняющие беременность, отягощенные беременностью или являющиеся показанием для акушерской помощи При необходимости идентифицировать конкретное состояние используют дополнительный код (класс I). Исключены: бессимптомный статус инфицирования вирусом иммунодефицита человека [ВИЧ] (Z21) болезнь, вызванная вирусом иммунодефицита человека [ВИЧ] (B20-B24) лабораторное подтверждение носительства вируса иммунодефицита человека [ВИЧ] (R75) акушерский столбняк (A34) послеродовая(ый): . инфекция (O86.-) . сепсис (O85) случаи, когда медицинская помощь матери оказывается в связи с ее заболеванием, которое явно или предположительно влияет на плод (O35-O36)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7048, 'Туберкулез, осложняющий беременность, деторождение и послеродовой период', 'O98.0', 7047, 'O98', 0, 'Состояния, классифицированные в рубриках A15-A19');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7049, 'Сифилис, осложняющий беременность, деторождение и послеродовой период', 'O98.1', 7047, 'O98', 0, 'Состояния, классифицированные в рубриках A50-A53');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7050, 'Гонорея, осложняющая беременность, деторождение и послеродовой период', 'O98.2', 7047, 'O98', 0, 'Состояния, классифицированные в рубрике A54');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7051, 'Другие инфекции, передающиеся преимущественно половым путем, осложняющие беременность, деторождение и послеродовой период', 'O98.3', 7047, 'O98', 0, 'Состояния, классифицированные в рубриках A55-A64');
