INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7053, 'Другие вирусные болезни, осложняющие беременность, деторождение и послеродовой период', 'O98.5', 7047, 'O98', 0, 'Состояния, классифицированные в рубриках A80-B09, B25-B34');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7054, 'Протозойные инфекции, осложняющие беременность, деторождение и послеродовой период', 'O98.6', 7047, 'O98', 0, 'Состояния, классифицированные в рубриках B50-B64');
