INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7056, 'Инфекционные и паразитарные болезни матери, осложняющие беременность, деторождение и послеродовой период, неуточненные', 'O98.9', 7047, 'O98', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7057, 'Другие болезни матери, классифицированные в других рубриках, но осложняющие беременность, роды и послеродовой период', 'O99', 7043, 'O94-O99', 9, 'Примечание. Эта рубрика включает состояния, осложняющие беременность, отягощенные беременностью или являющиеся главной причиной для оказания акушерской помощи и для которых в алфавитном указателе не приведены специальные рубрики в классе XV. При необходимости идентифицировать конкретное состояние используют дополнительный код. Исключены: инфекционные и паразитарные болезни (O98.-) травмы, отравления и некоторые другие последствия воздействия внешних причин (S00-T98) случаи, когда медицинская помощь матери оказывается в связи с ее заболеванием, которое явно или предположительно влияет на плод (O35-O36)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7058, 'Анемия, осложняющая беременность, деторождение и послеродовой период', 'O99.0', 7057, 'O99', 0, 'Состояния, классифицированные в рубриках D50-D64');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7059, 'Другие болезни крови и кроветворных органов и отдельные нарушения с вовлечением иммунного механизма, осложняющие беременность, деторождение и послеродовой период', 'O99.1', 7057, 'O99', 0, 'Состояния, классифицированные в рубриках D65-D89 Исключены: кровотечения с нарушениями коагуляции (O46.0, O67.0, O72.3)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7060, 'Болезни эндокринной системы, расстройства питания и нарушения обмена веществ, осложняющие беременность, деторождение и послеродовой период', 'O99.2', 7057, 'O99', 0, 'Состояния, классифицированные в рубриках E00-E90 Исключены: сахарный диабет (O24.-) недостаточность питания (O25) послеродовой тиреоидит (O90.5)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7061, 'Психические расстройства и болезни нервной системы, осложняющие беременность, деторождение и послеродовой период', 'O99.3', 7057, 'O99', 0, 'Состояния, классифицированные в рубриках F00-F99 и G00-G99 Исключены: постнатальная депрессия (F53.0) связанные с беременностью поражения периферических нервов (O26.8) послеродовой психоз (F53.1)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7062, 'Болезни системы кровообращения, осложняющие беременность, деторождение и послеродовой период', 'O99.4', 7057, 'O99', 0, 'Состояния, классифицированные в рубриках I00-I99 Исключены: кардиомиопатия в послеродовом периоде (O90.3) гипертензивные расстройства (O10-O16) акушерская эмболия (O88.-) венозные осложнения и тромбоз церебровенозного синуса во время: . родов и в послеродовом периоде (O87.-) . беременности (O22.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7063, 'Болезни органов дыхания, осложняющие беременность, деторождение и послеродовой период', 'O99.5', 7057, 'O99', 0, 'Состояния, классифицированные в рубриках J00-J99');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7064, 'Болезни органов пищеварения, осложняющие беременность, деторождение и послеродовой период', 'O99.6', 7057, 'O99', 0, 'Состояния, классифицированные в рубриках K00-K93 Исключены: поражение печени во время беременности, деторождения и в послеродовом периоде (O26.6)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7065, 'Болезни кожи и подкожной клетчатки, осложняющие беременность, деторождение и послеродовой период', 'O99.7', 7057, 'O99', 0, 'Состояния, классифицированные в рубриках L00-L99 Исключен: герпес беременных (O26.4)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7066, 'Другие уточненные болезни и состояния, осложняющие беременность, деторождение и послеродовой период', 'O99.8', 7057, 'O99', 0, 'Сочетание состояний, классифицированных в рубриках O99.0-O99.7 Состояния, классифицированные в рубриках C00-D48, H00-H95, M00-M99, N00-N99, и Q00-Q99 Исключены: инфекции мочеполовых путей при беременности (O23.-) инфекции мочеполовых путей после родоразрешения (O86.0-O86.3) медицинская помощь матери в связи с установленной или предполагаемой аномалией органов таза (O34.-) послеродовая острая почечная недостаточность (O90.4)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7067, 'ОТДЕЛЬНЫЕ СОСТОЯНИЯ, ВОЗНИКАЮЩИЕ В ПЕРИНАТАЛЬНОМ ПЕРИОДЕ', 'P00-P96', NULL, NULL, 10, 'Включены: нарушения, возникающие в перинатальном периоде, даже если смерть или болезнь наступают позднее\nИсключены: врожденные аномалии, деформации и хромосомные нарушения (Q00-Q99) болезни эндокринной системы, расстройства питания и нарушения обмена веществ (E00-E90) травмы, отравления и некоторые другие последствия воздействия внешних причин (S00-T98) новообразования (C00-D48) столбняк новорожденного (A33)\nЭтот класс содержит следующие блоки:\nP00-P04 Поражение плода и новорожденного, обусловленные состояниями матери, осложнениями беременности, родов и родоразрешения\nP05-P08 Расстройства, связанные с продолжительностью беременности и ростом плода\nP10-P15 Родовая травма\nP20-P29 Дыхательные и сердечно-сосудистые нарушения, характерные для перинатального периода\nP35-P39 Инфекционные болезни, специфичные для перинатального периода\nP50-P61 Геморрагические и гематологические нарушения у плода и новорожденного\nP70-P74 Преходящие эндокринные нарушения и нарушения обмена веществ, специфические для плода и новорожденного\nP75-P78 Расстройства системы пищеварения у плода и новорожденного\nP80-P83 Состояния, затрагивающие кожные покровы и терморегуляцию у плода и новорожденного\nP90-P96 Другие нарушения, возникающие в перинатальном периоде\n\nЗвездочкой отмечена следующая рубрика:\nP75* Мекониевый илеус');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7068, 'ПОРАЖЕНИЯ ПЛОДА И НОВОРОЖДЕННОГО, ОБУСЛОВЛЕННЫЕ СОСТОЯНИЯМИ МАТЕРИ, ОСЛОЖНЕНИЯМИ БЕРЕМЕННОСТИ, РОДОВ И РОДОРАЗРЕШЕНИЯ', 'P00-P04', 7067, 'P00-P96', 5, 'Включены: перечисленные ниже состояния матери, когда они уточнены как причина смерти или болезни плода или новорожденного');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7069, 'Поражения плода и новорожденного, обусловленные состояниями матери, которые могут быть не связаны с настоящей беременностью', 'P00', 7068, 'P00-P04', 10, 'Исключены: влияние на плод и новорожденного: . осложнений беременности у матери (P01.-) . эндокринных и обменных нарушений у матери (P70-P74) . вредных веществ, проникающих через плаценту или грудное молоко (P04.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7070, 'Поражения плода и новорожденного, обусловленные гипертензивными расстройствами у матери', 'P00.0', 7069, 'P00', 0, 'Поражения плода и новорожденного, обусловленные состояниями матери, классифицированными в рубриках O10-O11, O13-O16');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7071, 'Поражения плода и новорожденного, обусловленные болезнями почек и мочевых путей у матери', 'P00.1', 7069, 'P00', 0, 'Поражения плода и новорожденного, обусловленные состояниями матери, классифицированными в рубриках N00-N39');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7072, 'Поражения плода и новорожденного, обусловленные инфекционными и паразитарными болезнями у матери', 'P00.2', 7069, 'P00', 0, 'Поражения плода и новорожденного, обусловленные инфекционными болезнями матери, классифицированными в рубриках A00-B99 иJ10-J11, но без проявления этих болезней у плода и новорожденного Исключены: инфекции, специфичные для перинатального периода (P35-P39) инфекции половых путей и другие локализованные инфекции у матери (P00.8)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7073, 'Поражения плода и новорожденного, обусловленные хроническими болезнями системы кровообращения и дыхания у матери', 'P00.3', 7069, 'P00', 0, 'Поражения плода и новорожденного, обусловленные состояниями матери, классифицированными в рубриках I00-I99, J00-J99, Q20-Q34, но не включенные в рубрики P00.0, P00.2');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7074, 'Поражения плода и новорожденного, обусловленные расстройствами питания у матери', 'P00.4', 7069, 'P00', 0, 'Поражения плода и новорожденного, обусловленные состояниями матери, классифицированными в рубриках E40-E64 Недостаточность питания матери БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7075, 'Поражения плода и новорожденного, обусловленные травмой у матери', 'P00.5', 7069, 'P00', 0, 'Поражения плода и новорожденного, обусловленные состояниями матери, классифицированными в рубриках S00-T79');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7076, 'Поражения плода и новорожденного, обусловленные проведением хирургического вмешательства у матери', 'P00.6', 7069, 'P00', 0, 'Исключены: поражения при родоразрешении с помощью кесарева сечения (P03.4) повреждение плаценты при амниоцентезе, кесаревом сечении или хирургическом вмешательстве (P02.1) предшествующее хирургическое вмешательство на матке и тазовых органах (P03.8) прерывание беременности (влияние на плод) (P96.4)');
