INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7123, 'Замедленный рост и недостаточность питания плода', 'P05', 7122, 'P05-P08', 4, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7124, '"Маловесный" для гестационного возраста плод', 'P05.0', 7123, 'P05', 0, 'Обычно относится к состоянию, когда масса тела ниже, а длина тела выше 10-го перцентиля для гестационного возраста. "Маловесный" для рассчитанного срока');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7125, 'Малый размер плода для гестационного возраста', 'P05.1', 7123, 'P05', 0, 'Обычно относится к состоянию, когда масса и длина тела ниже 10-го перцентиля для гестационного возраста. Маленький для рассчитанного срока плод Маленький и "маловесный" для рассчитанного срока');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7126, 'Недостаточность питания плода без упоминания о "маловесном" или маленьком для гестационного возраста', 'P05.2', 7123, 'P05', 0, 'Новорожденный, у которого нет снижения массы тела, но отмечаются признаки недостаточности питания, такие, как сухость, шелушение кожи и неполноценность подкожной клетчатки. Исключены: недостаточность питания плода с упоминанием о: . "маловесности" для гестационного возраста (P05.0) . малом размере для гестационного возраста (P05.1)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7127, 'Замедленный рост плода неуточненный', 'P05.9', 7123, 'P05', 0, 'Задержка роста плода БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7128, 'Расстройства, связанные с укорочением срока беременности и малой массой тела при рождении, не классифицированные в других рубриках', 'P07', 7122, 'P05-P08', 4, 'Примечание. При наличии данных о массе тела при рождении и гестационном возрасте предпочтение следует отдавать показателю массы тела при рождении. Включены: перечисленные состояния без дальнейшего уточнения, являющиеся причиной смерти, заболевания или оказания дополнительной помощи новорожденному Исключено: состояние малой массы тела при рождении в связи с замедленным ростом и недостаточностью питания плода (P05.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7129, 'Крайне малая масса тела при рождении', 'P07.0', 7128, 'P07', 0, 'Масса тела при рождении 999 г или менее.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7130, 'Другие случаи малой массы тела при рождении', 'P07.1', 7128, 'P07', 0, 'Масса тела при рождении 1000-2499 г.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7131, 'Крайняя незрелость', 'P07.2', 7128, 'P07', 0, 'Срок беременности менее 28 полных недель (менее 196 полных дней).');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7132, 'Другие случаи недоношенности', 'P07.3', 7128, 'P07', 0, 'Срок беременности 28 полных недель или более, но менее 37 полных недель (196 полных дней, но менее 259 полных дней). Недоношенность БДУ');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7133, 'Расстройства, связанные с удлинением срока беременности и большой массой тела при рождении', 'P08', 7122, 'P05-P08', 3, 'Примечание: При наличии данных о массе тела при рождении и гестационном возрасте предпочтение следует отдавать показателю массы тела при рождении. Включены: перечисленные состояния без дальнейшего уточнения, являющиеся причиной смерти, болезни или оказания дополнительной помощи плоду или новорожденному');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7134, 'Чрезмерно крупный ребенок', 'P08.0', 7133, 'P08', 0, 'Эту рубрику обычно используют, когда масса тела при рождении составляет 4500 г или более. Исключены: синдром: . новорожденного от матери, страдающей диабетом (P70.1) . новорожденного от матери, страдающей гестационным диабетом (P70.0)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7135, 'Другие "крупновесные" для срока дети', 'P08.1', 7133, 'P08', 0, 'Другие плоды или новорожденные, масса тела или рост которых при рождении превышают соответствующие данному сроку беременности показатели, независимо от ее срока.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7136, 'Переношенный ребенок, но не "крупновесный" для срока', 'P08.2', 7133, 'P08', 0, 'Плод или ребенок, родившийся в срок беременности 42 полные недели или более (294 дня ил более), масса тела или рост которого не превышает соответствующие сроку беременности показатели. Переношенность БДУ');
