INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7192, 'Асфиксия при родах', 'P21', 7187, 'P20-P29', 3, 'Примечание. Эту рубрику не следует использовать при низких показателях по шкале Апгар без упоминания об асфиксии или других дыхательных расстройствах. Исключены: внутриутробная гипоксия или асфиксия (P20.-)');
