INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(7194, 'Средняя и умеренная асфиксия при рождении', 'P21.1', 7192, 'P21', 0, 'Нормальное дыхание в течение первой минуты после рождения не установилось, но частота сердцебиений 100 ударов/мин или более, незначительный мышечный тонус, незначительный ответ на раздражение. Оценка по шкале Апгур 4-7 через 1 мин после рождения Синяя асфиксия');
