INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(9869, 'ОТРАВЛЕНИЯ ЛЕКАРСТВЕННЫМИ СРЕДСТВАМИ, МЕДИКАМЕНТАМИ И БИОЛОГИЧЕСКИМИ ВЕЩЕСТВАМИ', 'T36-T50', 8587, 'S00-T98', 15, 'Включены: случаи: . передозировки этих веществ . неправильной выдачи или приема по ошибке этих веществ\nИсключены: злоупотребление средствами, не вызывающими зависимость (F55) неблагоприятные реакции ["повышенная чувствительность", "реакция" и т.д.] на правильно введенное и соответствующее назначению вещество; эти случаи классифицируются согласно характеру неблагоприятной реакции, такой как: . гастрит, вызванный приемом аспирина (K29.-) . изменения крови (D50-D76) . дерматит: . контактный (L23-L25) . вызванный веществами, принятыми внутрь (L27.-) . нефропатия (N14.0-N14.2) . неуточненная патологическая реакция на лекарственное средство (T88.7) лекарственная зависимость и психические расстройства и нарушения поведения вследствие употребления психоактивных веществ (F10-F19) лекарственная реакция и отравление, влияющие на плод и новорожденного (P00-P96) патологическая лекарственная интоксикация (F10-F19)');
