INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(10175, 'Неблагоприятные эффекты, не классифицированные в других рубриках', 'T78', 10126, 'T66-T78', 7, 'Примечание.Эту рубрику следует использовать при кодировании по единичной причине как первичный код для идентификации неблагоприятных эффектов, не классифицированных в других рубриках, вызванных неизвестной, неопределенной или неточно обозначенной причиной. При множественном кодировании эту рубрику можно использовать как дополнительный код для идентификации воздействия состояний, классифицированных в других рубриках. Исключены: осложнения, вызванные хирургическим и терапевтическим вмешательством НКДР (T80-T88)');
