INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(12625, 'СЛУЧАЙНОЕ ОТРАВЛЕНИЕ И ВОЗДЕЙСТВИЕ ЯДОВИТЫМИ ВЕЩЕСТВАМИ', 'X40-X49', 15062, 'W00-X59', 10, '[См. вышеуказанные подрубрики кодов места происшествия]\nПримечание. Уточненный перечень лекарственных средств и других веществ, классифицированных в трехзначных рубриках, см. в Таблице лекарственных средств и химических веществ в Алфавитном указателе. Наличие алкоголя вместе с веществами, указанными ниже, можно идентифицировать путем использования дополнительных кодов Y90-Y91.\nВключены: случайная передозировка, неправильное назначение лекарственного средства, прием его по ошибке или невниманию несчастные случаи при использовании лекарственных средств, медикаментов и биологических веществ при терапевтических и хирургических процедурах отравление, не уточненнное как случайное или преднамеренное\nИсключены: введение лекарственного средства с целью убийства или самоубийства, с целью нанесения вреда или при других обстоятельствах, классифицированных в рубриках X60-X69, X85-X90, Y10-Y19 соответствующее назначению, правильно введенное в терапевтических или профилактических дозах лекарственное средство как причина неблагоприятной реакции (Y40-Y59)');
