INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(13369, 'ПОВРЕЖДЕНИЕ С НЕОПРЕДЕЛЕННЫМИ НАМЕРЕНИЯМИ', 'Y10-Y34', 10344, 'V01-Y98', 25, '[См. вышеуказанные подрубрики кодов места происшествия]\nПримечание. Этот блок включает случаи, когда доступной информации недостаточно, чтобы медицинские и юридические эксперты могли сделать вывод о том, является ли данный инцидент несчастным случаем, самоповреждением или насилием с целью убийства или нанесения повреждений. Сюда включены самоповреждения, исключая отравления, при отсутствии указаний на их характер - случайный или преднамеренный.');
