INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(15063, 'ОСЛОЖНЕНИЯ ТЕРАПЕВТИЧЕСКИХ И ХИРУРГИЧЕСКИХ ВМЕШАТЕЛЬСТВ', 'Y40-Y84', 10344, 'V01-Y98', 4, 'Включены: осложнения, связанные с медицинскими приборами и устройствами любые неблагоприятные реакции, связанные с соответствующими назначениями, правильно введенными в терапевтических или профилактических дозах лекарственными средствами случайное нанесение вреда больному во время хирургического и терапевтического вмешательства хирургические и терапевтические процедуры как причина анормальной реакции пациента или отдаленного осложнения без упоминания о случайном нанесении вреда больному во время их выполнения\nИсключены: случайная передозировка, неправильное назначение или прием лекарственного средства по ошибке (X40-X44)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(13666, 'ЛЕКАРСТВЕННЫЕ СРЕДСТВА, МЕДИКАМЕНТЫ И БИОЛОГИЧЕСКИЕ ВЕЩЕСТВА, ЯВЛЯЮЩИЕСЯ ПРИЧИНОЙ НЕБЛАГОПРИЯТНЫХ РЕАКЦИЙ ПРИ ТЕРАПЕВТИЧЕСКОМ ПРИМЕНЕНИИ', 'Y40-Y59', 15063, 'Y40-Y84', 20, 'Примечание. Перечень специфических лекарственных средств, классифицированных в четырехзначных подрубриках, см. в Таблице лекарственных средств и химических веществ в Алфавитном указателе.\nИсключены: несчастные случаи, обусловленные несовершенной техникой введения лекарств, медикаментов или биологических веществ во время терапевтических и хирургических процедур (Y60-Y69)');
