INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14021, 'ПОСЛЕДСТВИЯ ВОЗДЕЙСТВИЯ ВНЕШНИХ ПРИЧИН ЗАБОЛЕВАЕМОСТИ И СМЕРТНОСТИ', 'Y85-Y89', 10344, 'V01-Y98', 5, 'Примечание. Рубрики Y85-Y89 должны использоваться для обозначения обстоятельств как причины смерти, нарушения или инвалидности от последствий или отдаленных проявлений, которые сами классифицированы в других рубриках. Понятие "последствия" включает состояния, описанные как таковые или как отдаленные проявления, развившиеся через год или более после происшедшего события.');
