INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14052, 'Алкогольная интоксикация легкой степени', 'Y91.0', 14051, 'Y91', 0, 'Запах алкоголя при выдыхании, легкие нарушения поведенческих функций и реакций или незначительные трудности координации движений.');
