INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(11829, 'Укус или ужаливание неядовитым насекомым и другими неядовитыми членистоногими. В школе, другом учреждении и общественном административном районе', 'W57.2', 11826, 'W57', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14061, 'ФАКТОРЫ, ВЛИЯЮЩИЕ НА СОСТОЯНИЕ ЗДОРОВЬЯ НАСЕЛЕНИЯ И ОБРАЩЕНИЯ В УЧРЕЖДЕНИЯ ЗДРАВООХРАНЕНИЯ', 'Z00-Z99', NULL, NULL, 7, 'Примечание. Данный класс не следует использовать для проведения сравнений на международном уровне или для первичного кодирования причин смерти.\nРубрики Z00-Z99 предназначены для тех случаев, когда в качестве\n"диагноза" или "проблемы" указаны не болезнь, травма или внешняя\nпричина, относящиеся к разделам A00-Y89, а иные обстоятельства.\nТакое положение может возникнуть в основном в двух случаях.\nа) Когда инвалид, в данное время необязательно являющийся больным, обращается в учреждение здравоохранения с какой-либо специальной целью, например для получения незначительной по объему помощи или для обслуживания в связи с текущим состоянием: в качестве донора органа или ткани, для профилактической вакцинации или обсуждения проблемы, которая сама по себе не вызвана болезнью или травмой.\nб) Когда имеют место какие-либо обстоятельства или проблемы, влияющие на здоровье, однако в данный момент сами по себе не являющиеся болезнью или травмой. Такие факторы могут быть обнаружены в ходе обследований состояния здоровья населения, во время которых индивид может быть болен или здоров; они также могут быть зарегистрированы как дополнительные обстоятельства, которые следует иметь в виду при обращении за помощью по поводу какого-либо заболевания или повреждения.\nЭтот класс содержит следующие блоки:\nZ00-Z13 Обращения в учреждения здравоохранения для медицинского осмотра и обследования\nZ20-Z29 Потенциальная опасность для здоровья, связанная с инфекционными болезнями\nZ30-Z39 Обращения в учреждения здравоохранения в связи с обстоятельствами, относящимися к репродуктивной функции\nZ40-Z54 Обращения в учреждения здравоохранения в связи с необходимостью проведения специфических процедур и получения медицинской помощи\nZ55-Z65 Потенциальная опасность для здоровья, связанная с социально-экономическими и психосоциальными обстоятельствами\nZ70-Z76 Обращения в учреждения здравоохранения в связи с другими обстоятельствами\nZ80-Z99 Потенциальная опасность для здоровья, связанная с личным или семейным анамнезом и определенными обстоятельствами, влияющими на здоровье');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14062, 'ОБРАЩЕНИЯ В УЧРЕЖДЕНИЯ ЗДРАВООХРАНЕНИЯ ДЛЯ МЕДИЦИНСКОГО ОСМОТРА И ОБСЛЕДОВАНИЯ', 'Z00-Z13', 14061, 'Z00-Z99', 11, 'Примечание. Неспецифические отклонения от нормы, обнаруженные в ходе этих обследований, следует кодировать рубриками R70-R94.\nИсключены: обследования в связи с беременностью и репродуктивной функцией (Z30-Z36, Z39.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14063, 'Общий осмотр и обследование лиц, не имеющих жалоб или установленного диагноза', 'Z00', 14062, 'Z00-Z13', 8, 'Исключены: медицинское обследование в административных целях (Z02.-) специальные скрининговые обследования (Z11-Z13)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14064, 'Общий медицинский осмотр', 'Z00.0', 14063, 'Z00', 0, 'Проверка здоровья БДУ Периодический осмотр (ежегодный) (физикальный) Исключены: общая проверка здоровья: . определенных групп населения (Z10.-) . ребенка грудного и раннего возраста (Z00.1)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14065, 'Рутинное обследование состояния здоровья ребенка', 'Z00.1', 14063, 'Z00', 0, 'Проведение тестов для оценки развития ребенка грудного или раннего возраста Исключено: наблюдения за здоровьем подкидышей или других здоровых детей грудного или раннего возраста (Z76.1-Z76.2)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14066, 'Обследование в период быстрого роста в детстве', 'Z00.2', 14063, 'Z00', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14067, 'Обследование с целью оценки состояния развития подростка', 'Z00.3', 14063, 'Z00', 0, 'Состояние пубертатного развития');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14068, 'Общее психиатрическое обследование, не классифицированное в других рубриках', 'Z00.4', 14063, 'Z00', 0, 'Исключено: обследование в судебно-медицинских целях (Z04.6)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14069, 'Обследование потенциального донора органов и тканей', 'Z00.5', 14063, 'Z00', 0, NULL);
