INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14071, 'Другие общие осмотры', 'Z00.8', 14063, 'Z00', 0, 'Медицинский осмотр в ходе массовых обследований населения');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14072, 'Другие специальные осмотры и обследования лиц, не имеющих жалоб или установленного диагноза', 'Z01', 14062, 'Z00-Z13', 10, 'Включено: рутинное обследование определенных систем Исключены: обследование: . в административных целях (Z02.-) . при подозрении на заболевания (состояния) (не подтвержденные) (Z03.-) специальные скрининговые обследования (Z11-Z13)');
