INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14308, 'ОБРАЩЕНИЯ В УЧРЕЖДЕНИЯ ЗДРАВООХРАНЕНИЯ В СВЯЗИ С НЕОБХОДИМОСТЬЮ ПРОВЕДЕНИЯ СПЕЦИФИЧЕСКИХ ПРОЦЕДУР И ПОЛУЧЕНИЯ МЕДИЦИНСКОЙ ПОМОЩИ', 'Z40-Z54', 14061, 'Z00-Z99', 15, 'Примечание. Рубрики Z40-Z54 предназначены для кодирования причин, дающих основание для получения медицинской помощи. Они могут быть использованы для тех случаев, когда больные, ранее лечившиеся по поводу какой-либо болезни или травмы, получают последующую или профилактическую помощь или помощь, необходимую для выздоровления или закрепления результатов лечения, для лечения остаточных явлений, а также для устранения или предупреждения рецидивов.\nИсключено: последующее обследование при медицинском наблюдении после лечения (Z08-Z09)');
