INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14474, 'Проживание в одиночестве', 'Z60.2', 14471, 'Z60', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14475, 'Трудности, связанные с принятием другой культуры', 'Z60.3', 14471, 'Z60', 0, 'Миграция Изменения в социальном статусе');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14476, 'Социальная изоляция и остракизм', 'Z60.4', 14471, 'Z60', 0, 'Социальная изоляция и остракизм на основе личностных характеристик, таких, как необычная внешность, болезнь или поведение. Исключена: жертва враждебной дискриминации по расовому или религиозному признаку (Z60.5)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14477, 'Жертва ощущаемой дискриминации и гонения', 'Z60.5', 14471, 'Z60', 0, 'Преследование или дискриминация (предполагаемые или реальные), основанные на принадлежности к некоторым группам (по цвету кожи, религии, этническому происхождению и т.д.), а не личностных характеристиках. Исключены: социальная изоляция и остракизм (Z60.4)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14478, 'Другие проблемы, связанные с факторами социального окружения', 'Z60.8', 14471, 'Z60', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14479, 'Проблема, связанная с факторами социального окружения, неуточненная', 'Z60.9', 14471, 'Z60', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14480, 'Проблемы, связанные с неблагоприятными жизненными событиями в детстве', 'Z61', 14421, 'Z55-Z65', 10, 'Исключен: синдром жестокого обращения (T74.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14481, 'Потеря в детстве любимых родственников', 'Z61.0', 14480, 'Z61', 0, 'Потеря эмоционально близких родственников, таких, как родители, брат или сестра, очень близкий друг или любимый человек, вследствие смерти, длительного отсутствия или отстранения.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14482, 'Отлучение ребенка от дома', 'Z61.1', 14480, 'Z61', 0, 'Помещение в приют, больницу или другое учреждение, вызывающее психологический стресс, или призыв в армию из дома на длительный период.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14483, 'Изменение семейных взаимоотношений родственников в детстве', 'Z61.2', 14480, 'Z61', 0, 'Появление другого лица в семье в результате неблагоприятных для ребенка изменений во взаимоотношениях родственников (это может быть новый брак родителей или рождение другого ребенка).');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14484, 'События, приводящие к снижению самооценки в детстве', 'Z61.3', 14480, 'Z61', 0, 'События, завершающиеся самооценкой ребенка (например, неудача каком-либо деле с высокой личной ответственностью, обнаружение или раскрытие постыдных или бесчестных эпизодов личной или семейной жизни и другие факторы, дающие повод к самоуничижению).');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14485, 'Проблемы, связанные с возможным сексуальным изнасилованием ребенка лицом, принадлежащим к группе первичной поддержки', 'Z61.4', 14480, 'Z61', 0, 'Проблемы, связанные с какой-либо формой физического контакта между взрослым членом семьи и ребенком или другими способами, вызывающими сексуальное возбуждение и независимо от желания ребенка приводящее к половому контакту (например, прикосновения или манипуляции с половыми органами, намеренное обнажение половых органов или молочных желез).');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14486, 'Проблемы, связанные с возможным сексуальным насилием в отношении ребенка посторонним лицом', 'Z61.5', 14480, 'Z61', 0, 'Проблемы, связанные с различными манипуляциями с половыми органами и молочными железами, с раздеванием, ласками и другими действиями с ребенком, склоняющими или имеющими целью склонять его к половому акту, лицом, значительно более старшим по возрасту, не являющимся членом семьи и использующим свой статус или положение, либо действующим против желания ребенка.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14487, 'Проблемы, связанные с возможным физическим насилием по отношению к ребенку', 'Z61.6', 14480, 'Z61', 0, 'Проблемы, связанные с инцидентами, при которых ребенку в прошлом были нанесены травмы кем-либо из взрослых, проживающих в доме, требующие медицинского ухода (переломы, явные кровоподтеки), либо при которых ребенок подвергся жестоким формам насилия (избиение тяжелыми или острыми предметами, ожоги или связывание).');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14488, 'Личные потрясения, перенесенные в детстве', 'Z61.7', 14480, 'Z61', 0, 'Переживания, которые могут оказать влияние на будущее ребенка, вызванные например, похищением, природными катаклизмами с угрозой для жизни, увечьем, угрожающим безопасности или собственному восприятию, или травмой, нанесенной дорогому для ребенка человеку в его присутствии.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14489, 'Другие неблагоприятные жизненные события в детстве', 'Z61.8', 14480, 'Z61', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14490, 'Неблагоприятное жизненное событие в детстве неуточненное', 'Z61.9', 14480, 'Z61', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14491, 'Другие проблемы, связанные с воспитанием ребенка', 'Z62', 14421, 'Z55-Z65', 9, 'Исключен: синдром жестокого обращения (T74.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14492, 'Неадекватность заботы и контроля со стороны родителей', 'Z62.0', 14491, 'Z62', 0, 'Неинформированность родителей о том, что делает ребенок и где он находится, плохой контроль за ним, отсутствие постоянной заботы о нем и попыток предупредить рискованные ситуации, в которых он может оказаться.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14493, 'Излишняя опека со стороны родителей', 'Z62.1', 14491, 'Z62', 0, 'Система воспитания, результатом которой является инфантильность и отсутствие у ребенка самостоятельности и независимости.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14494, 'Воспитание в закрытом учреждении', 'Z62.2', 14491, 'Z62', 0, 'Групповое воспитание, при котором ответственность родителей в значительной степени переложена на персонал различных форм учреждений (таких, как дома ребенка, приюты для сирот, школы-интернаты) или терапевтическая помощь в течение длительного времени в больнице, учреждении для выздоравливающих или санатории, когда ребенок находится по крайней мере без одного родителя.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14495, 'Враждебное отношение и несправедливые претензии к ребенку', 'Z62.3', 14491, 'Z62', 0, 'Негативное отношение родителей к ребенку как к личности, резкость и постоянная раздражительность по отношению к некоторым моментам в поведении ребенка (например, постоянные оскорбления за любые поступки в доме или напрасные обвинения ребенка).');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14496, 'Эмоциональная заброшенность ребенка', 'Z62.4', 14491, 'Z62', 0, 'Тон разговора родителей с ребенком пренебрежительный или безразличный. Отсутствие интереса к ребенку, чуткого отношения к его трудностям, похвалы и поддержки, раздражительная реакция на нарушение в поведении ребенка и отсутствие ласкового и теплого отношения к ребенку.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14497, 'Другие проблемы, связанные с недостатками в воспитании ребенка', 'Z62.5', 14491, 'Z62', 0, 'Отсутствие обучающего и игрового опыта у ребенка');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14498, 'Неприемлемое давление со стороны родителей и другие отрицательные факторы воспитания ребенка', 'Z62.6', 14491, 'Z62', 0, 'Родители заставляют ребенка делать то, что выходит за рамки принятых норм, не соответствует половой принадлежности (например, одевание мальчика в девичье платье), возрасту (например, требование от ребенка еще недоступной ему ответственности за свои поступки), его желанию или возможностям.');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14499, 'Другие уточненные проблемы, связанные с воспитанием ребенка', 'Z62.8', 14491, 'Z62', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14500, 'Проблема, связанная с воспитанием ребенка, неуточненная', 'Z62.9', 14491, 'Z62', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14501, 'Другие проблемы, связанные с близкими людьми, включая семейные обстоятельства', 'Z63', 14421, 'Z55-Z65', 10, 'Исключены: синдром жестокого обращения (T74.-) проблемы, связанные с: . неблагоприятными жизненными событиями в детстве (Z61.-) . воспитанием (Z62.-)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14502, 'Проблемы, связанные с взаимоотношениями супругов или партнеров', 'Z63.0', 14501, 'Z63', 0, 'Разногласия между супругами (партнерами), ведущие к длительной или выраженной утрате контроля взаимоотношений, враждебности, нежеланию понять друг друга или постоянной атмосфере грубого межличностного насилия (избиения, драки).');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14503, 'Проблемы взаимоотношений с родителями или родственниками жены или мужа', 'Z63.1', 14501, 'Z63', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14504, 'Недостаточная семейная поддержка', 'Z63.2', 14501, 'Z63', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14505, 'Отсутствие члена семьи', 'Z63.3', 14501, 'Z63', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14506, 'Исчезновение или смерть члена семьи', 'Z63.4', 14501, 'Z63', 0, 'Чувство вины перед умершим');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14507, 'Распад семьи в результате разделения или развода', 'Z63.5', 14501, 'Z63', 0, 'Отчужденность');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14508, 'Зависимый член семьи, нуждающийся в уходе в домашних условиях', 'Z63.6', 14501, 'Z63', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14509, 'Другие стрессовые жизненные события, влияющие на семью и экономические условия', 'Z63.7', 14501, 'Z63', 0, 'Беспокойство (нормальное) о заболевшем члене семьи Связанные со здоровьем проблемы в семье Болезнь или нарушение у члена семьи Изолированная семья');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14510, 'Другие уточненные проблемы, связанные с группой первичной поддержки', 'Z63.8', 14501, 'Z63', 0, 'Разногласия в семье БДУ Чрезмерный эмоциональный уровень в семье Неадекватные или расстроенные взаимоотношения в семье');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14511, 'Проблемы, связанные с группой первичной поддержки, неуточненные', 'Z63.9', 14501, 'Z63', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14512, 'Проблемы, связанные с определенными психосоциальными обстоятельствами', 'Z64', 14421, 'Z55-Z65', 5, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14513, 'Проблемы, связанные с нежелательной беременностью', 'Z64.0', 14512, 'Z64', 0, 'Исключено: наблюдение за течением беременности у женщины, подвергающейся риску вследствие социальных проблем (Z35.7)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14514, 'Проблемы, связанные с многодетностью', 'Z64.1', 14512, 'Z64', 0, 'Исключено: наблюдение за течением беременности у многорожаюшей женщины (Z35.4)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14515, 'Поиск и использование физических, пищевых и химических веществ, известных как вредные и опасные', 'Z64.2', 14512, 'Z64', 0, 'Исключена: наркотическая зависимость - см. Алфавитный указатель');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14516, 'Поиск и принятие действий поведенческого и психологического характера, известных как вредные и опасные', 'Z64.3', 14512, 'Z64', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14517, 'Конфликт с советником', 'Z64.4', 14512, 'Z64', 0, 'Конфликт с: . лицом, ответственным за испытуемого . социальным работником');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14518, 'Проблемы, связанные с другими психосоциальными обстоятельствами', 'Z65', 14421, 'Z55-Z65', 8, 'Исключена: текущая травма - см.Алфавитный указатель');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14519, 'Обвинение в гражданском или уголовном преступлении без заключения в тюрьму', 'Z65.0', 14518, 'Z65', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14520, 'Тюремное заключение и другое вынужденное лишение свободы', 'Z65.1', 14518, 'Z65', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14521, 'Проблемы, связанные с освобождением из тюрьмы', 'Z65.2', 14518, 'Z65', 0, NULL);
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14522, 'Проблемы, связанные с другими юридическими обстоятельствами', 'Z65.3', 14518, 'Z65', 0, 'Арест Опекунство ребенка или хлопоты об алиментах Судебная тяжба Судебное преследование');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14523, 'Жертва преступления и терроризма', 'Z65.4', 14518, 'Z65', 0, 'Жертва пытки');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14524, 'Жертва стихийного бедствия, военных и других враждебных действий', 'Z65.5', 14518, 'Z65', 0, 'Исключена: жертва ощущаемой дискриминации или гонения (Z60.5)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14525, 'Другие уточненные проблемы, связанные с обстоятельствами психологического характера', 'Z65.8', 14518, 'Z65', 0, NULL);
