INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14528, 'Консультации, касающиеся сексуальных отношений, поведения и ориентации', 'Z70', 14527, 'Z70-Z76', 6, 'Исключено: консультирование по поводу контрацепции или детородной функции (Z30-Z31)');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14529, 'Консультирование, касающееся отношения к сексуальным вопросам', 'Z70.0', 14528, 'Z70', 0, 'Лицо, испытывающее смущение, робость или другое затруднение в связи с сексуальными вопрсами');
INSERT INTO class_mkb (id, name, code, parent_id, parent_code, node_count, additional_info) VALUES(14530, 'Консультирование, касающееся сексуального поведения или сексуальной ориентации', 'Z70.1', 14528, 'Z70', 0, 'Пациент, озабоченный: . импотенцией . отсутствием реакции . промискуитетом . сексуальной ориентацией');
